quests[11094] = { id = 11094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Them All!", description = "Commander {name}, stand at attention! You are to take a battalion of Skybreakers and sack the Scryers' outpost located at the foot of the Netherwing Fields. With the Sanctum of the Stars destroyed, our lines of communication to our posts at Eclipse Point and Illidari Point will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the attack!", sourceObjective = "Deliver news of your mission along with the Dragonmaw Flare Gun to Arcanist Thelis at the Sanctum of the Stars in Shadowmoon Valley.", progress = "Settle down, child.", completion = "It is good that you came to us. Perhaps we can use this attack to our advantage and turn the tables on the Dragonmaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[11095] = { id = 11095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Hobb", description = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.\n\nI want you to let them come, {name}.\n\n<Thelis nods.>\n\nYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Hobb. He is standing guard right outside this building.", sourceObjective = "Give the Dragonmaw Flare to Commander Hobb at the Sanctum of the Stars in Shadowmoon Valley.", progress = "<Hobb nods.>", completion = "<Hobb grins.>\n\nThe deadliest trap ever laid...", sourceObjectiveStatus = "unverified-source-field" }
quests[11096] = { id = 11096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat from Above", description = "So you want to join the Skyguard?  Well, I know you can fly... but can you fight?\n\nThe Skyguard is sworn to protect Shattrath from the dangers that loom above us, both near and far.  The Gordunni ogres who dwell in the Barrier Hills to the north are an immediate threat to us.\n\nReaching the ogres has been problematic for Shattrath's ground units.  That's where we come in.  See what you can do to help contain them.", sourceObjective = "Slay any 20 Gordunni Ogres in the Barrier Hills and return to Yuula in Shattrath City.", progress = "Have you completed your task, {name}?", completion = "Good job, ace.  I've a feeling you're going to fit in well with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[11097] = { id = 11097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deadliest Trap Ever Laid", description = "Take these Scryer medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Scryer soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.", sourceObjective = "Assist Commander Hobb and the Scryers in defending the Sanctum of the Stars. Once all of the Dragonmaw forces have been defeated, return to Overlord Mor'ghor at Dragonmaw Base Camp with the Scryer Medals.", progress = "Did you crush them under your boot, commander?", completion = "<Mor'ghor laughs.>\n\nHAH! I knew you wouldn't let me down, commander! I want you to lead a raid on the Sanctum of the Stars at least once per day. They will have no choice but to leave Shadowmoon!", sourceObjectiveStatus = "unverified-source-field" }
quests[11098] = { id = 11098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Skettis!", description = "The Barrier Hills are only one of the fronts where we've been deployed.  A less immediate but far more dangerous threat looms from beyond the Skethyl Mountains, from within the arakkoa city of Skettis.\n\nA few months ago our scouts detected a huge increase in arakkoa activity there.  Several attacks against Shattrath followed.  We've stationed forces outside of their city since.\n\nTake these explosives to Sergeant Doryn at Blackwind Landing, just outside Skettis.  Tell him you're a new recruit.", sourceObjective = "Take the Explosives Package to Sky Sergeant Doryn at Blackwind Landing outside Skettis.", progress = "You've something for me, lad?", completion = "Thanks for the supplies; we'll put them to good use!  A new recruit?  Well, let's see what you're made of.", sourceObjectiveStatus = "unverified-source-field" }
quests[11099] = { id = 11099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Them All!", description = "Commander {name}, stand at attention! You are to take a battalion of Skybreakers and sack the Aldor outpost located northwest of our beloved Black Temple. With the Altar of Sha'tar destroyed, our lines of communication to our posts at Coilskar will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the attack!", sourceObjective = "Deliver news of your mission and the Dragonmaw Flare Gun to Anchorite Ceyla at the Altar of Sha'tar.", progress = "Settle down, child.", completion = "It is good that you came to us. Perhaps we can use this attack to our advantage and turn the tables on the Dragonmaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[11100] = { id = 11100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Arcus", description = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.\n\nI want you to let them come, {name}.\n\n<Ceyla nods.>\n\nYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus. He is standing guard right outside this building.", sourceObjective = "Give the Dragonmaw Flare to Commander Arcus at the Altar of Sha'tar in Shadowmoon Valley.", progress = "<Arcus nods.>", completion = "<Arcus grins.>\n\nThe deadliest trap ever laid...", sourceObjectiveStatus = "unverified-source-field" }
quests[11101] = { id = 11101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deadliest Trap Ever Laid", description = "Take these Aldor medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Aldor soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.", sourceObjective = "Assist Commander Arcus and the Aldor in defending the Altar of Sha'tar. Once all of the Dragonmaw forces have been defeated, return to Overlord Mor'ghor at Dragonmaw Base Camp with the Aldor Medals.", progress = "Did you crush them under your boot, commander?", completion = "<Mor'ghor laughs.>\n\nHAH! I knew you wouldn't let me down, commander! I want you to lead a raid on the Altar of Sha'tar at least once per day. They will have no choice but to leave Shadowmoon!", sourceObjectiveStatus = "unverified-source-field" }
quests[11102] = { id = 11102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombing Run", description = "You can fly around as a crow... so what!  Ever annihilate something on the ground while you were flying?  Want to?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.\n\nWant to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!", sourceObjective = "Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.", progress = "You take out their stacks of fel cannonballs yet?", completion = "Well, well, well, I guess you had it in you after all.  Good work.  Maybe Old Man Keller was wrong about you after all.\n\n<Sky Sergeant Vanderlip smirks.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11103] = { id = 11103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sage No More", progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty." }
quests[11104] = { id = 11104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restorer No More", progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty." }
quests[11105] = { id = 11105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion No More", progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty." }
quests[11106] = { id = 11106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender No More", progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty." }
quests[11107] = { id = 11107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bow to the Highlord", description = "I am unworthy to even carry a message directed at you, sir. Please forgive me for this indulgence. Overlord Mor'ghor has requested your presence in his chambers at once!", sourceObjective = "Speak to Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "You are the first highlord of the Dragonmaw, {name}. The master himself has chosen to come here to promote you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11108] = { id = 11108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Illidan Stormrage", description = "Come, highlord {name}. Illidan himself awaits us!", sourceObjective = "Meet Illidan Stormrage. Seek out Barthamus in the Lower City of Shattrath should you survive.", completion = "I was the first, you know. The abandoned child of a monster...\n\n<Barthamus shakes his head.>\n\nWe owe you everything, {name}. You have single-handedly shattered the Dragonmaw empire and gathered enough information to keep my brethren occupied for ten lifetimes.\n\nIt is not much but there is something that we can offer... My kin have each offered to join you on your mission in Outland. Simply ask and they will bond with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11109] = { id = 11109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorus the Cobalt Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11110] = { id = 11110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfas the Purple Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11111] = { id = 11111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onyxien the Onyx Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11112] = { id = 11112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suraku the Azure Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11113] = { id = 11113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voranaku the Violet Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11114] = { id = 11114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zoya the Veridian Netherwing Drake", sourceObjective = "It is an honor to meet you, {name}. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11117] = { id = 11117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch the Wild Wolpertinger!", description = "Here now. Ye hear that? There be sounds in them hills. Those're the wolpertingers! Wily beasts, they are, attracted by the smells o' Brewfest. I've a mind to catch me some, but I knocked me shin and can't outrun the buggers. Ye can help me, though!\n\nTake this net and cast it over the little blighters. Bring me a good five of 'em and I'll make it worth yer while!\n\nOne more thing - ye gotta use Synthebrew Goggles to spot 'em! Let me know if ya need a pair.", sourceObjective = "Goldark Snipehunter has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be wearing Synthebrew Goggles to see them.", progress = "Were ye drunk enough to see the little buggers?", completion = "Well, lookee there! Ye've got yerself a right bushel o' wolpertingers, ye do!\n\n<He takes a deep drink from his tankard.>\n\nI'll tell ye what I'm gonna do. Since ye're such a spot-on hunter, I'll let ye keep one'a these fer yer very own!", sourceObjectiveStatus = "unverified-source-field" }
quests[11118] = { id = 11118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pink Elekks On Parade", description = "Getting drunk is a time-honored tradition at Brewfest -- it's damn near required! Thing is, I'm getting reports across Azeroth saying the celebration's plagued by hallucinations!  We can't have that!\n\nThese elekks can't be harmed by normal weapons -- they pass right through 'em -- so take this fabulous piece of gnomish machinery, visit the other beer gardens, and zap 'em to oblivion.\n\nRemember, you have to be wearing Synthebrew Goggles to see 'em! Talk to me if you need a pair.", sourceObjective = "Visit the beer gardens outside Stormwind, Darnassus, and the Exodar, zap three elekks at each location, and return to Goldark Snipehunter. You must be wearing Synthebrew Goggles to see the pink elekks.", progress = "Are those pesky pink elekks gone yet?", completion = "Good work! Pink elekks... what a preposterous notion!", sourceObjectiveStatus = "unverified-source-field" }
quests[11119] = { id = 11119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Bash'ir Landing!", description = "Heya, <boyo/girly>!  Up fer some fun are ye?\n\nEvery couple o' hours, me aether-techs launch an assault on Bash'ir Landing, far ta the northeast in the Blade's Edge Mountains.  They say that they're there 'studying' the Bash'ir crystalforge, but it's an assault; there be no two ways about it.  We use the crystalforge to resupply, and there's always extra to be sold.\n\nGo on down ta the landin' pad and speak with the aether-tech apprentice.  He'll tell ye when the next mission is ta launch.", sourceObjective = "Speak with the Aether-tech Apprentice at Skyguard Outpost in the Blade's Edge Mountains.", completion = "Despite how Keller cares to characterize it, I prefer to think of our missions as research-oriented.\n\nBut yes, we do resupply the Skyguard while we're there.  That is if we can stay long enough to do so.\n\nYou look like you'd be willing to keep the ethereals off of our backs.  If you can manage to for long enough, we'll sell you surplus items that we create at the crystalforge, so bring your apexis shards and crystals!\n\nWe leave in 0 |4minute:minutes;.", sourceObjectiveStatus = "unverified-source-field" }
quests[11120] = { id = 11120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pink Elekks On Parade", description = "Look. We're running a business here. People being drunk? It's good business. But I'll tell ya one thing that puts a cramp in the profits - hallucinations. Wouldn't ya know it, the boys are reporting that the sot- er, the loyal customers are seeing pink elekks everywhere.\n\nI don't need my customers unsettled. Look, take this ray and travel to the other beer gardens to take care of 'em for me, would ya? And be sure to wear Synthebrew Goggles! Talk to me if ya need a pair.", sourceObjective = "Visit the beer gardens outside of Silvermoon, Thunder Bluff, and the Undercity, zap three elekks at each location, and return to Glodrak Huntsniper. You must be wearing Synthebrew Goggles to see the pink elekks.", progress = "Ya clear up that little problem we talked about?", completion = "Ya did good, kid. Here, take this as payment for the job ya did.", sourceObjectiveStatus = "unverified-source-field" }
quests[11122] = { id = 11122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There and Back Again", description = "So you want to help out at Brewfest?  I've got the perfect task for ya.  I'll put you on one of my racing rams and you head down to Kharanos.  I've got some kegs I need to pick up.  \n\nFlynn Firebrew is waiting on a hill near a stack of kegs.  He'll toss you a keg when you get near, then you run the keg back here and toss the keg to Pol Amberstill.  You can only carry one at a time.  \n\nReady?", sourceObjective = "Get a keg from Flynn Firebrew in Kharanos and return it to Pol Amberstill.   If you lose your ram, ask Neill Ramstein for another.", progress = "I need those kegs!  So, what are yeh waitin' for!?!", completion = "Thanks a lot for your help!  As long as Brewfest is going and the Dark Iron dwarves are attacking, I'll need some help shipping kegs.  So if you want to work for more tokens, talk to me every day.\n\nBut enough about that, I need to pay you for the job you just did.  Here are your tokens, have fun at Brewfest!", sourceObjectiveStatus = "unverified-source-field" }
quests[11123] = { id = 11123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "nspecting the Ruins", description = "Poor James never recovered from the destruction of the Shady Rest and the murder of his family. The boys and I are doing what we can to find the monsters who did this.\n\nI've sent our best investigator, Inspector Tarem, out to the ruins, but this is too big a job for any one man. If you'd lend Tarem a hand, we'd appreciate it. Light knows, we'd all like to be out there helping.\n\nThe main road will lead you to the inn, but take care. Your journey will take you beyond the protection of my soldiers.", sourceObjective = "Speak to Inspector Tarem at the Shady Rest Inn.", completion = "It's good to see that Captain Vimes is finally assigning others to this investigation.\n\nI've used a reflective powder to dust the area. It will reveal suspicious objects and markings, helping you to focus your efforts. Look over anything the dust illuminates.", sourceObjectiveStatus = "unverified-source-field" }
quests[11124] = { id = 11124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "nspecting the Ruins", description = "If you follow the road south from the village, and then west toward the Barrens, you'll come across the ruins of the Shady Rest Inn.\n\nTheramore has sent an investigator to discover how the inn met its fate. I had a man placed in that inn as a spy and I don't trust in the competence of these humans to uncover what happened.\n\nWhatever you find, don't give a scrap of it to that investigator. We'll handle this ourselves.", sourceObjective = "Investigate the Shady Rest Inn in at the border of the Barrens in Dustwallow Marsh.", completion = "<The inspector regards you with what can only be distrust.>\n\nI've been told that you're to... aid in this investigation. Very well, then.\n\nI've been using this powder to search the ruins for clues that might help identify the attackers. It will illuminate anything that might have been involved in the attack. Don't hesitate to examine anything that looks suspicious.", sourceObjectiveStatus = "unverified-source-field" }
quests[11126] = { id = 11126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors Among Us", description = "It's good to meet you, {class}. I've come to Theramore to help eliminate the problem of the deserters. Not only have some of the men abandoned their posts, but some have filtered back into the town.\n\nThese deserter agents are spreading lies and propaganda, hoping to convince others to join their ranks.\n\nThey're at virtually every guard post throughout the town and the docks. Find them, expose them, and discredit them. At this point, anything more risks inspiring more sympathy for them.", sourceObjective = "Confront 5 Deserter Agitators and return to Calia Hastings near the docks in Theramore.", progress = "Have you driven the deserter agents from Theramore?", completion = "Well done, {name}. I think we managed to catch them off guard. Their agents probably thought themselves safe within the city walls.\n\nGiven time, the agitators will return and spread their lies again. We'll use the time you've bought to shut out the deserters further.", sourceObjectiveStatus = "unverified-source-field" }
quests[11128] = { id = 11128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propaganda War", description = "The deserter agents were doing far more than just chatting up the guards. We've found a number of leaflets the deserters somehow managed to smuggle in on a ship in the docks.\n\nThe ship used to transport the leaflets is still in Theramore, at the farthest dock. If you can sneak aboard and capture the rest of their propaganda documents, their agents will lose their most powerful tool. Be careful! The ship is manned by seasoned privateers and the cargo is probably being kept in the captain's quarters.", sourceObjective = "Bring the Deserter Propaganda to Calia Hastings near the docks in Theramore.", progress = "Did you manage to find and capture the remaining propaganda leaflets?", completion = "<The SI:7 agent nods in approval.>\n\nExcellent. All that remains is to discredit the deserters so that they'll never gain a foothold in Theramore again, and I have just the plan to do it.", sourceObjectiveStatus = "unverified-source-field" }
quests[11129] = { id = 11129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyle's Gone Missing!", description = "Help, {name}! My prized puppy, Kyle, has run away! I just know he's running around Bloodhoof Village, lost and hungry.\n\nWill you find him and feed him? Once he eats he will settle down and come home.\n\nTo feed him you will need to find food. His favorite meal is tender strider meat. Just venture east and you should find plenty of striders. Hunt one down and take its succulent meat to Kyle. When you see Kyle in town, put the meat down and he is sure to come to you.", sourceObjective = "Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied.\n\nFeed Kyle Tender Strider Meat and return to Ahab Wheathoof.", progress = "Did you find Kyle?", completion = "Fantastic work, {name}! Kyle came home as soon as he ate and went straight to bed. Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[11130] = { id = 11130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oooh, Shinies!", description = "Come closer, <man/sweetheart>! Let ol' Griftah look at yer shiny things....\n\nHmm. Yeh, yeh, not bad, but ya can do better. Much, much better.\n\n<Griftah leans in and whispers.>\n\nThere be priceless shinies everywhere, {name}, ya just gotta know where to look! It be yer lucky day; I know a fella who can help ya find more shinies than ya can ever carry.\n\nVisit my ol' friend, Budd, near Zul'Aman and show him this here. Ya be tellin' him ol' Griftah sent ya and he'll let ya in on his new project.", sourceObjective = "Griftah wants you to take Griftah's Note to Budd in the Ghostlands, just outside of Zul'Aman.", progress = "<Budd eyes the note suspiciously.>\n\nWhat have you there, {class}?", completion = "<Budd reads the note.>\n\nAhh! A friend of Griftah? Welcome!\n\nYou have impeccable timing, friend. As fate would have it, I recently lost my latest partners. Tragic, truly, but great rewards often have a high price. Best not to dwell on the negative!\n\nYou've doubtlessly heard of my countless exploits and discoveries. Well, all of that was nothing compared to this! Truth is, we're close to making history here at Zul'Aman and, by fate's decree, you're in on the ground floor!", sourceObjectiveStatus = "unverified-source-field" }
quests[11131] = { id = 11131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Fires!", description = "You must help us!  The Headless Horseman is attacking the village.  Fires are everywhere!  The children aren't safe!\n\nPlease, {name}, join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  Put out all the fires and we may yet be saved!", sourceObjective = "The Costumed Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Costumed Orphan Matron.", progress = "{name}, you promised to save the children!", completion = "Oh, thank you!  May the Light bless your good works, kind sir.  The shadow of the Dark Horseman yet looms, but at least, for now, the village is safe from his flames.", sourceObjectiveStatus = "unverified-source-field" }
quests[11132] = { id = 11132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promises, Promises...", description = "My inscrutable theories confirm rumors of vast treasure in Zul'Aman. There'll be mounts and mansions for everyone! First things first, though. You must earn your share, after all....\n\nOur initial efforts here haven't gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk.\n\nForget the crew, I need that map! Succeed, and you'll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul'Aman!", sourceObjective = "Budd Nedreck in Hatchet Hills wants you to retrieve his map from High Priest Nalorakk's terrace in Zul'Aman.", progress = "Ahh yes, {name}, isn't it?\n\nHave you recovered my map yet?", completion = "<Budd looks a bit shocked.>\n\nOh? You've found it?\n\nAhem, I mean, of course you have! Well done, {class}.\n\nLet me see if I can find you a little something nice... ahh yes, this should do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11133] = { id = 11133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discrediting the Deserters", description = "I've altered the leaflets you captured from the deserters' mercenary friends at the docks. Now, anyone who reads them will get an entirely different view of the deserters and their aims.\n\nIf we distribute these to enough of the guards, the deserters will be too embarrassed to ever reestablish their presence within our walls.\n\n<Calia hands you a stack of the altered leaflets.>\n\nWhy don't you get started while I plan our next move?", sourceObjective = "Calia Hastings wants you to distribute the Altered Leaflets to 6 Theramore Guards, then report back to her near the docks in Theramore.", progress = "I thought I heard laughter coming from the barracks. Did you distribute those leaflets I gave you?", completion = "<Calia chuckles as you describe the guards' reactions to the propaganda.>\n\nJust as I'd hoped! I think it's safe to say any deserter agents who try to infiltrate Theramore will be laughed right out of town!", sourceObjectiveStatus = "unverified-source-field" }
quests[11134] = { id = 11134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Deserters", description = "Now that we've eliminated the deserters from Theramore, it's time to complete this operation. My local contacts have reported that the deserters base their operations in a ship moored on a small island to the southeast of the docks.\n\nArresting their leader, Gavis Greyshield, should cause the others to lose their will to fight. Find him within the ship and convince him to surrender. I wouldn't be surprised if he puts up a bit of a fight for show, but then surrenders when he understands he can't win.", sourceObjective = "Capture Gavis Greyshield, then report to Calia Hastings near the docks in Theramore.", progress = "Have you completed your assault on the deserter base?", completion = "Gavis' request isn't as outlandish as it might sound. With the proper handling, Lady Jaina can return the deserters to the fold, but that is her decision, of course.\n\nIt's been a pleasure working with you, {name}. Without your help, I doubt the operation would've gone so smoothly. When I make my report in Stormwind, it will name you as the {class} who ended the deserter threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11135] = { id = 11135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Headless Horseman", description = "The Headless Horseman is driven away, but he will return as long as Hallow's End looms.  {name}, end our misery, and the insane lament of the Horseman.  Face him when he is joined with his head, and destroy it!\n\nHe rests in the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades.  Find his pumpkin shrine and say this:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nGo, {name}.  And may the Light go with you.", sourceObjective = "Find the Headless Horseman's pumpkin Shrine.", completion = "The origin of this shrine is unknown, but there is no doubt to whom it pays homage...", sourceObjectiveStatus = "unverified-source-field" }
quests[11136] = { id = 11136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disturbing Development", description = "Reports from our scout patrols have recently taken a disturbing turn. They tell of men wearing red Defias bandanas walking the Dreadmurk Shore north of Theramore's walls.\n\nWreckage in the area suggests they may be survivors of a shipwreck, but our information is limited. Captain Wymor at Sentry Point, a guard tower to the north of the city, is looking for help in following up on the reports.", sourceObjective = "Report to Captain Wymor at Sentry Point.", completion = "<The captain makes no effort to hide that he's assessing your abilities.>\n\nSo you've heard about the recent shipwreck off the coast? Good, I could use some help confirming my suspicions about the survivors. Welcome aboard, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11137] = { id = 11137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "efias in Dustwallow?", description = "My scouts have reported a shipwreck just off the beach to the northeast. Shipwrecks aren't all that unusual out here, but the reports also indicated the survivors were all wearing red bandanas!\n\nThe Defias are craftsmen and guildsmen, not sailors. What are they doing at the site of a shipwreck on a continent they've no interest in?\n\nTheir leader is rumored to reside on a large island just off the coast to the northeast of the tower. Kill him and retrieve any documents you find in his possession.", sourceObjective = "Obtain the Defias Orders from Garn Mathers and bring them to Captain Wymor at Sentry Point.", progress = "Were you able to track down their leader?", completion = "<Captain Wymor accepts the orders from you and reads over them.>\n\nWhat in the world could 'precious cargo' refer to? The Defias have done some small time smuggling back in lands of Stormwind, but this seems out of their league. The language of these orders suggests a wealthy or noble patron.", sourceObjectiveStatus = "unverified-source-field" }
quests[11138] = { id = 11138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "enn McGill", description = "From the wording of the orders you recovered, it looks like the first priority of the Defias will be to locate and secure whatever cargo they possessed.\n\nSI:7 has had a salvage diver named Renn McGill working out of Theramore for some time. When he heard about the shipwreck, Renn went north to dive near the islands the Defias now occupy.\n\nIf we're to beat the Defias to this cargo, we'll need his help. Look for him in the waters northeast of a small island just north of the island you visited earlier.", sourceObjective = "Bring the Defias Orders to Renn McGill in the waters off the Dreadmurk Shore.", progress = "Well met, {class}. What brings you out here?", completion = "<Renn looks over the orders.>\n\nSo there was valuable cargo on board! We have to locate it before the Defias recover it. These guys are no divers, but we're going to need some of their gear if you're to help me find the cargo.", sourceObjectiveStatus = "unverified-source-field" }
quests[11139] = { id = 11139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "econdhand Diving Gear", description = "There's plenty of wreckage strewn across the bottom of the water from here to Alcaz, and the Defias have already got divers out there looking around. With the help of some of their gear, we can get you suited up and ready to join the hunt, but you'll have to do some creative \"borrowing\" first.\n\nSearch this island for a crate of diving gear and something to repair it with. When you've got them, bring them to me and I'll have your gear ready in no time!", sourceObjective = "Bring the Tool Kit and Damaged Diving Gear to Renn McGill in the Dustwallow Marsh.", progress = "Let's see what you managed to \"borrow\" from the Defias.", completion = "Wow, this is in worse shape than I'd thought, and these tools...\n\nWell, I said I'd get this back into working condition for you, so I'd better get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[11140] = { id = 11140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ecover the Cargo!", description = "Well, I was able to make enough repairs to this gear to let you dive for awhile, anyway. I wouldn't count on it holding out for a long time, though.\n\nThe wreckage of the ship is strewn along the bottom from the east coast of this island out toward Alcaz Island. While that helm holds out, locate pieces of the wreckage on the bottom between this island and Alcaz. Use this salvage kit to search the wreckage for pieces of the cargo. Be careful not to venture too close to Alcaz Island. Those hydra are fierce.", sourceObjective = "Bring 6 Salvaged Strongboxes to Renn McGill in Dustwallow Marsh.", progress = "Did your search of the wreckage reveal anything about the Defias cargo?", completion = "<Renn rifles through the contents of the strongboxes you recovered.>\n\nGood work. Now, let's see if our 'precious cargo' is in here....", sourceObjectiveStatus = "unverified-source-field" }
quests[11141] = { id = 11141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "aina Must Know", description = "You must bring news of our findings to Lady Jaina without delay! If the Defias were transporting a prisoner, there's no telling who it might be or if the person is still alive!\n\nOne thing is for certain, {name}. The Defias wouldn't go to all this trouble for some petty grudge. Their prisoner must have been someone of importance. Lady Jaina would know better than anyone else what these findings mean. You'll find her at the top of the mage tower at Theramore's center.", sourceObjective = "Speak with Lady Jaina Proudmoore in Theramore.", completion = "You and Renn have done excellent work in bringing this information to light and reporting it immediately. There's no denying the Defias have hatched some sinister plan to strike at Stormwind and its allies. There's a level of complexity here that's beyond anything they've ever attempted, which means they must have a wealthy sympathizer somewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[11142] = { id = 11142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "urvey Alcaz Island", description = "It looks like Renn's hunch about Alcaz Island was right. We need to survey that island, but it would take a whole brigade of troops to fight our way in there.\n\nTheramore's defenses can't weather such a hit, so I've arranged with Cassa Crimsonwing, the apprentice to Theramore's gryphon master, to allow you to use one of her beasts to survey Alcaz from the air.\n\nAlcaz Island holds the key to the mystery of the Defias' involvement in this kidnapping.", sourceObjective = "Speak to Cassa Crimsonwing and use one of her gryphons to survey Alcaz Island. When your survey is complete, speak with Lady Jaina Proudmoore in Theramore.", progress = "Have you completed your aerial survey of Alcaz Island?", completion = "<Lady Jaina listens intently as you report the results of your aerial survey.>\n\nA rune circle, dragonkin? The Defias have allied themselves with HER? The traitor?\n\n<Lady Jaina composes herself and prepares to explain.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11143] = { id = 11143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Connection", description = "I've spoken with Inspector Tarem regarding the evidence you gathered from the ruins of the Shady Rest Inn. He seems certain that the hoofprints and the shield you found there point to the Grimtotem clan of tauren.\n\nWith reports of Grimtotem activity on the rise in the marsh, this has to be more than a mere coincidence. I'm sending you to speak with Captain Darill, who is something of an expert on the Grimtotems. Follow the road north out of town to North Point tower. It's the second outpost on the road.", sourceObjective = "Report to Captain Darill at North Point.", completion = "Captain Vimes thinks the Grimtotems are behind the destruction of the Shady Rest Inn? They wouldn't have been first on my list of suspects, but if Captain Vimes sent you here to follow up on a lead, he must have his reasons. Regardless, the Grimtotems have been a thorn in our side for some time and we're always glad to have the extra help.", sourceObjectiveStatus = "unverified-source-field" }
quests[11144] = { id = 11144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "onfirming the Suspicion", description = "The Grimtotems may be the most warlike of all the tauren clans, but they're by no means unorganized. If they're the ones who put the torch to the Shady Rest Inn, they'll have had orders from one of their clan elders.\n\nThere's a large Grimtotem settlement called Blackhoof Village to the northwest. They've been using it as a base to attack the tower, but I'll bet that you'll find the orders you're looking for there. Check the village's elders for traces of the orders you seek.", sourceObjective = "Bring the Grimtotem Battle Plan to Captain Darill at North Point Tower.", progress = "Were you able to find any trace of the orders?", completion = "<Captain Darill glances at the battle plan.>\n\nI'd say it doesn't get any clearer than this. They've taken it upon themselves to fight back against human settlements in the area and I have little doubt Theramore is next on their list.", sourceObjectiveStatus = "unverified-source-field" }
quests[11145] = { id = 11145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "risoners of the Grimtotems", description = "We're doing all we can to keep the Grimtotem raiders at bay, but they keep launching assaults on the tower. Even worse, they've managed to discover and capture the patrols the captain sends out to gather information and safeguard the road.\n\nI suspect the captives are being held in Blackhoof Village, to the northwest. Knowing the Grimtotems, the defenders of the village probably carry the keys to the prisoners' cages with them. I don't care what you have to do, {class}, just bring back my men alive.", sourceObjective = "Sergeant Lukas at North Point Tower wants you to free 5 Theramore Prisoners.", progress = "Did you manage to free the captives at Blackhoof Village?", completion = "The freed captives have already begun returning from Blackhoof Village. The information the captain is receiving from the prisoners will give us an advantage in our next battle against the Grimtotems.\n\nYou have my thanks and that of the men.", sourceObjectiveStatus = "unverified-source-field" }
quests[11146] = { id = 11146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "aptor Captor", description = "The patch of swamp to the northeast is home to a particularly nasty breed of raptors. We've lost more than one unwary soldier to them, but I think we can turn them against our Grimtotem neighbors.\n\nTake this rope and use it to capture bloodfen raptors or bloodfen screechers that you've subdued. I wouldn't try to capture one of the beasts until you've weakened them quite a bit in combat. It's going to be quite a struggle.", sourceObjective = "Sergeant Lukas at North Point Tower wants you to capture 6 raptors. You can capture either Bloodfen Raptors or Bloodfen Screechers.", progress = "Did you capture those raptors?", completion = "You look a little scratched up, but nothing major. You're certainly in a lot better shape than the Grimtotems will be when our new raptor friends get done with them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11147] = { id = 11147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "nleash the Raptors", description = "Now that we've got our raptors, our next move is to \"encourage\" them to attack the Grimtotems at Blackhoof Village to the northwest.\n\nI've got a leftover haunch of... well, it doesn't really matter what it is. It'll be your bait. Set it down on the ground in Blackhoof Village near the windmill in the center of the settlement. The raptors should take care of the rest, if their training took.", sourceObjective = "Sergeant Lukas at North Point Tower wants you to place the Raptor Bait near the windmill in Blackhoof Village.", completion = "<The sergeant doesn't bother to hide his grin.>\n\nGood. That ought to forestall a raid or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[11148] = { id = 11148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "rms of the Grimtotems", description = "If the equipment you found at the ruins of the inn belonged to a Grimtotem attack party, there's likely to be more just like it within their camp to the northwest.\n\nWe haven't been able to gather much information about Blackhoof Village, but judging from the size of the raiding parties, there's a substantial force based there.\n\nDo whatever you have to to capture some of their equipment so that we can compare it with your findings from the inn.", sourceObjective = "Captain Darill at North Point Tower wants you to bring him 7 Blackhoof Armaments.", progress = "Did you get those weapons from Blackhoof Village?", completion = "<Captain Darill inspects the armaments you've brought from Blackhoof Village.>\n\nThere's no doubt about it. These match the description exactly, but there's just one problem -- these have never been used in battle. Blackhoof Village must not be the only Grimtotem post in the marsh.", sourceObjectiveStatus = "unverified-source-field" }
quests[11149] = { id = 11149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "abetha's Assistance", description = "I can't spare any men to help search for a second Grimtotem outpost, but I think I know of someone who might be able to help you.\n\nDeep in the Quagmire, to the south, there is a small farmstead owned by Tabetha. She may seem little more than an old hermit, but the truth is that she's a mage and scryer of some renown. Follow the road south to her farm and seek her help in finding the culprits responsible for the massacre at the Shady Rest Inn.", sourceObjective = "Speak with Tabetha at her farm.", completion = "So you want me to scry for Grimtotems, eh? And what will you say when I tell you there's no need?", sourceObjectiveStatus = "unverified-source-field" }
quests[11150] = { id = 11150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "aze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", sourceObjective = "Burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post, then return to Tabetha at her farm.", progress = "Have you put that torch to good use?", completion = "I hope the Grimtotems got the message. Any attempt to return will be met with far worse than a mere torch. My apprentices and I will see to that.", sourceObjectiveStatus = "unverified-source-field" }
quests[11151] = { id = 11151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ustice for the Hyals", description = "Although these Grimtotems were simply a nuisance to me, Captain Vimes will want to know of your deeds. Bring him the news that you have tracked down and dealt with those responsible for the burning of the Shady Rest Inn.\n\nIt's too late to save Jim Hyal's family, but perhaps the Grimtotems will think twice before attacking anyone connected to Theramore.", sourceObjective = "Speak to Captain Garran Vimes at Foothold Citadel in Theramore.", completion = "<The captain listens to your report intently.>\n\nWe have avenged James and his family, but not even that can restore what was destroyed.", sourceObjectiveStatus = "unverified-source-field" }
quests[11152] = { id = 11152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eace at Last", description = "I wish we had a way of letting James Hyal's wife and son know that we have brought their murderers to justice.\n\n<Captain Vimes produces a small wreath decorated with flowers.>\n\nThere are some who say that their spirits will know, even if we cannot reach them. It's not much, but I'd like you to lay this wreath at the Hyal family monument. It's one of the larger stones in the graveyard just north of Theramore's gates.", sourceObjective = "Captain Garran Vimes at Foothold Citadel wants you to lay the Wreath at the Hyal Family Monument.", progress = "Did you lay the wreath?", completion = "<Captain Vimes smiles slightly as you relate the events you witnessed at the Hyal family grave.>\n\nIt's good to know that they understand. You didn't tell them about James, did you?\n\nI'll deliver his wife's message to him, but I doubt he'll understand.", sourceObjectiveStatus = "unverified-source-field" }
quests[11153] = { id = 11153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Blockade", description = "All of our ships are sunk! We need your help to break the pirate blockade below in the Shattered Straits!\n\nTake these cluster bombs and hitch a ride on the zeppelin that Harrowmeiser has 'loaned' to us.  He'll fly you over the decks of those pirate scoundrels, and you make sure to give it to them good!\n\nIf you can't bomb them to smithereens, I'm afraid we'll never be able to break the blockade.", sourceObjective = "Take Petrov's Cluster Bombs and drop them on enough pirates to kill or destroy 25 Blockade Pirates and 10 Blockade Cannons. Once you've accomplished that, return to Bombardier Petrov at Westguard Keep.", progress = "We're talking again are we?  That must mean that you've done it!  You've shown those rotten Northsea pirates a thing or two!\n\nRight?", completion = "That's what I wanted to hear!  You've got the stuff, {name}, that's for sure!\n\nYou think maybe you could come back again tomorrow when we've made more cluster bombs?  I'd have you back out there right now, but my assistant, Feknut, isn't back from collecting more bat guano for them.\n\nI wonder what's taking him so long?", sourceObjectiveStatus = "unverified-source-field" }
quests[11154] = { id = 11154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scare the Guano Out of Them!", description = "You, yes you... I need your help!\n\nPetrov sent me up here to get bat guano for the cluster bombs he's making back at the keep. He sent me to my doom!\n\nThe darkclaw bats hang out in the Rivenwood to the north, but I'm not taking a step off of this platform unless it's to go home!\n\nBut you... you could get it for me! Yes? Pretty please?!!!\n\nHere, take these firecrackers. My thinking is that if you drop 'em underneath the bats, the guano will be scared right out of them!", sourceObjective = "Collect 10 Darkclaw Guano and deliver them to Engineer Feknut at Steel Gate.", progress = "Please tell me that you have the darkclaw guano?!", completion = "Ugh, what's that smell? Ack, it's you! Well, I guess I did send you on a smelly job!\n\nThank you, {class}. Don't worry, I'll get this stuff back to Petrov as soon as we get out of here.\n\n\n\nYou hear that guys? Lets get the hell out of here!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[11155] = { id = 11155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoveltusk Soup Again?", description = "With all of the strange disappearances of our livestock, we better resupply in a hurry, or the beasties around these parts will be the least of our worries!\n\nSeeing as I'm in charge of feeding this lot, I'm going to need you to head east and get me some meat. More to the point, I'm looking to cook us up some tender shoveltusk meat.\n\nJust beware the stags... they're mean!", sourceObjective = "Chef Kettleblack has asked you to obtain 6 Shoveltusk Meat and deliver them to her at Westguard Keep.", progress = "There's nothing as sumptuous as the tender meat carved from the flanks of a shoveltusk!", completion = "This will make a fine meal for the men.\n\n<The chef leans in closer to whisper in your ear.>\n\nHere, boy, take some for yourself. You look like you could use some more meat on your bones!", sourceObjectiveStatus = "unverified-source-field" }
quests[11156] = { id = 11156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "irehorn Raiders", description = "The Grimtotems up at Direhorn Post, just to the north, are getting bolder by the day. At night, you can often hear them chanting about their deeds in battle against people who've tried to settle here.\n\nThey're determined to drive us from Tabetha's farm even though she's trained generations of apprentices here. We've defended the farm as best we can, but Apprentice Garion was wounded in the last attack.\n\nGo to Direhorn Post and kill any Grimtotem you can find! The attacks must stop.", sourceObjective = "Kill 12 Direhorn Grimtotems and return to Apprentice Morlann at Tabetha's Farm.", completion = "<Apprentice Morlann nods.>\n\nGood. Can't say I'll miss the company, if you can call it that. You'd think at least in the middle of the swamp you'd get some privacy, you know?", sourceObjectiveStatus = "unverified-source-field" }
quests[11157] = { id = 11157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Clutches of Evil", description = "{name}, I don't trust anyone but you to take care of this.  I need the proto-drake eggs and proto-whelps in the burning forest to the southeast destroyed!\n\nSince we arrived here, the Ember Clutch has been ablaze; there must be some sort of perverse magic at work. And lately it seems to be growing. My men tell me that if we don't do something quickly, we'll be surrounded on all sides by the fire within a few weeks' time!\n\nGet down there and eliminate the threat by destroying those eggs and the proto-whelps.", sourceObjective = "Destroy 15 Proto-Drake Eggs and 15 Proto-Whelps, and then return to Captain Adams at Westguard Keep.", completion = "Good work! With any luck at all, the destruction of their egg clutches and whelps should drive off those fiery beasts and prevent that magical blaze from spreading.\n\nWait... what's that sound? It sounds like the beating of wings.", sourceObjectiveStatus = "unverified-source-field" }
quests[11158] = { id = 11158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "loodfen Feathers", description = "Are you startled by Brogg's presence here, little {race}? Don't worry. Goblins at Mudsprocket are Brogg's friends and you can be, too.\n\nBrogg left Brackenwall Village when new overlord not take revenge against black dragonkin for destroying old home and killing many of Brogg's old friends. Brogg come here to lay friends spirits to rest and avenge them, but Brogg need help preparing. For ritual, Brogg need feathers with strong magic, like ones worn by raptors at Bloodfen Burrow to the west of town.", sourceObjective = "Bring 5 Bloodfen Feathers to Brogg at Mudsprocket.", progress = "<Brogg looks at you hopefully.>\n\nYou bring Brogg feathers?", completion = "<Brogg accepts the feathers.>\n\nBrogg pleased with these feathers. Very strong magic. Brogg not know what raptors do to give feathers power, but raptor feathers always best for ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[11159] = { id = 11159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "pirits of Stonemaul Hold", description = "Brogg has completed the totem that will put the spirits of his friends to rest. When the dragonkin came, they killed all Stonemaul who did not flee. Brogg fled with Overlord Mok'Morokk, hoping to lead a counterattack with other Stonemaul survivors.\n\nThe counterattack never came and the spirits of the Stonemaul dead still haunt Brogg and the others. Take this totem north to Stonemaul Ruins and use it near ogre skeletons to draw the spirit to you. Defeat the spirit to give it rest with its bones.", sourceObjective = "Brogg, at Mudsprocket, wants you to put 10 Stonemaul Spirits to rest.", progress = "Brogg must know, have you brought peace to the violent spirits of the Stonemaul?", completion = "Brogg thanks you for your help, although he knows Overlord Mok'Morokk never will. At least surviving Stonemaul can finally focus on problems with the living and leave dead where they belong. Only one thing remains for Brogg to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11160] = { id = 11160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "anner of the Stonemaul", description = "When the dragons came and took over Brogg's old home, Stonemaul ogres fled and left everything behind, including clan's banner.\n\nBrogg knows banner was kept deep in Stonemaul ogre mound, but these days it's called Den of Flame. Brogg must have clan banner to get his revenge on dragons who killed his friends.\n\nBrogg's clan's old mound, Den of Flame, is northwest of Mudsprocket and crawling with dragonkin. Banner will be deep inside the cave. Be careful, {name}.", sourceObjective = "Retrieve the Stonemaul Banner and bring it to Brogg at Mudsprocket.", progress = "You bring Stonemaul banner?", completion = "You have Brogg's thanks, {name}. Brogg has big plans for clan banner.", sourceObjectiveStatus = "unverified-source-field" }
quests[11161] = { id = 11161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Essence of Enmity", description = "To make the totem Brogg will need for his ritual, he must use the essences of the creatures who killed his friends. The hate and anger of Brogg's enemies will fuel the magic of his vengeance.\n\nTrack down Firemane ash tails, scouts, or scalebanes and use Brogg's totem on their corpses. Only when the dragonkin die will they give up their essences.\n\nThe creatures you seek swarm over the Den of Flame to the northwest and the Stonemaul Ruins to the north.", sourceObjective = "Bring 10 Black Dragonkin Essences to Brogg at Mudsprocket.", progress = "Do you have the essences? Brogg must have them to avenge his friends!", completion = "You have Brogg's thanks, {name}. Once Brogg adds their magic to the totem, it will be able to redeem the spirits of Brogg's fallen friends.", sourceObjectiveStatus = "unverified-source-field" }
quests[11162] = { id = 11162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "hallenge to the Black Flight", description = "Brogg relishes the thought of taking his revenge on the black dragonkin of the marsh. {name}, you have been very helpful in preparing for this moment. Will you help?\n\nTake Brogg's clan banner and travel east until you see a cave like a dragon's mouth. At the entrance to that cave, plant Stonemaul banner and issue Brogg's challenge to Onyxia.\n\nBrogg and the Stonemaul will have their lands back!", sourceObjective = "Plant the Stonemaul Banner near the entrance to Onyxia's Lair, wait for Onyxia's response, then return to Brogg at Mudsprocket.", progress = "Brogg will have his revenge!", completion = "<Brogg listens as you recount your experience at the entrance to Onyxia's lair.>\n\nBrogg suspected Onyxia would be too much of a coward to confront you. Just like black dragonflight to attack when victory is guaranteed.\n\nBrogg is grateful for your help, {name}, and he will never forget what you have done for him. Brogg will never give up his quest to bring Stonemaul back where they belong.", sourceObjectiveStatus = "unverified-source-field" }
quests[11163] = { id = 11163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercover Sister", description = "<Donna looks around and then whispers to you.>\n\n{name}, what I'm about to tell you must remain confidential, understood?\n\nI've been sent by the Shattrath Peacekeepers to infiltrate Budd's gang here. Truth be told, since you first arrived you've been a key person of interest in my investigation. \n\nBut your deeds have since cleared you of any suspicion. In fact, for your slaying of the crazed warlord, Zul'Jin, I'm compelled to reward you for your efforts.", sourceObjective = "Report to Donna Brascoe to collect a reward for your heroism in Zul'Aman. Donna is currently stationed in the Ghostlands, just outside Zul'aman.", completion = "<Donna looks around and then whispers to you.>\n\n{name}, what I'm about to tell you must remain confidential, understood?\n\nI've been sent by the Shattrath Peacekeepers to infiltrate Budd's gang here. Truth be told, since you first arrived you've been a key person of interest in my investigation. \n\nBut your deeds have since cleared you of any suspicion. In fact, for your slaying of the crazed warlord, Zul'Jin, I'm compelled to reward you for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[11164] = { id = 11164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuskin' Raiders", description = "'Ey mon! You be new around 'ere, eh? Lemme ask a favor of ya.\n\nBudd's been refinin' his forest troll disguise. Says that he be close now - just be needin' one last touch. Tusks.\n\nMy skinnin' talents be wasted 'ere. Somethin' about yankin' troll tusks be makin me queasy. \n\nBring me back 10 troll tusks, eh mon?", sourceObjective = "Prigmon needs you to collect 10 Forest Troll Tusks from the trolls in Zul'Aman. Bring them to him at Budd's camp in the Ghostlands.", progress = "Hurry, mon!\n\nBudd be sendin' me into Zul'Aman alone to test his mask if I don't be givin' him those tusks soon!", completion = "Ahh yeah, these be just what I be needin'!\n\nHere be the payment I promised ya, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11165] = { id = 11165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Troll Among Trolls", description = "Lissen mon, there be sumthin' else needs doin fer ol' Prigmon.\n\nZungam, my good-fer-nuthin' cousin, be stuck inside Zul'Aman. He still be alive too - I seen his signal flare just last night!\n\nI should be lettin' him rot fer gettin' me tied up in this mess, but he be owin' me big money.\n\nDo what ya can to help him out, then leave the collectin' to me!", sourceObjective = "Prigmon has tasked you with locating and assisting his cousin Zungam, somewhere within Zul'Aman.", completion = "I be free!\n\nDey took most everyting when dey nabbed me, but here - take the last of my coin fer your troubles.\n\nAnd the least I can be doin' is stickin' around to offer my services....", sourceObjectiveStatus = "unverified-source-field" }
quests[11166] = { id = 11166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "X Marks... Your Doom!", description = "How did those fools fail? I told them to be careful - even gave them disguises to help them blend in. Ahh, well. The bright side of their failure is that this opportunity falls to you.\n\nSucceed, and you'll be well on your way to joining my crew and sharing in the immeasurable fame that will soon be mine. Not that I need any more, mind you.\n\nThere are yet a few portions of my map that require further exploration before our excavation can be initiated....", sourceObjective = "Enter Zul'Aman and visit Halazzi's Chamber, Jan'alai's Platform, and Akil'zon's Platform. Report the details of those areas to Budd, at his camp in the Ghostlands.", completion = "<Budd struggles to maintain his composure.>\n\nErr - So, {name} - it's, uhhh,  about time you returned. Yes - in fact you're holding up the entire operation.\n\nNow then, let's get to filling in this map....", sourceObjectiveStatus = "unverified-source-field" }
quests[11167] = { id = 11167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Plague", description = "Not long after Arthas condemned us to this wretched existence, we in the Royal Apothecary Society endeavored to create a plague of our own.  A plague that would devour all flesh: living, dead or undead.\n\nWe've succeeded in creating this plague and we're here to hand deliver it to the Scourge's doorstep.\n\nThe Alliance intercepted the ship carrying the latest strain engineered in our Undercity laboratories.  Head to the wreckage southeast of here and salvage whatever containers you can.", sourceObjective = "Apothecary Lysander at Vengeance Landing wants you to recover 10 Intact Plague Containers from the wrecked ship to the southeast.", progress = "Have you obtained the containers, {name}?", completion = "It's good that you're back in one piece.  The danger of becoming infected from handling these containers is not non-existent.  I suppose I should've warned you about that earlier.", sourceObjectiveStatus = "unverified-source-field" }
quests[11168] = { id = 11168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiking the Mix", description = "I've a feeling the long trip across the sea is affecting the effectiveness of our plague.  What is needed is a potent toxin to boost the potency of the strain.\n\nThe crabs near this beach are a distant relative of the much smaller brown-shelled tidecrawler.  The smaller tropical variety produces a paralytic toxin strong enough to knock out an ogre.\n\nAs we all know bigger is better!  The much larger glands on the local variety should prove more potent.  Bring me a few!", sourceObjective = "Bring 3 Giant Toxin Glands from Giant Tidecrawlers to Apothecary Lysander at Vengeance Landing in Howling Fjord.", progress = "Have you obtained the toxin glands I seek, {name}?", completion = "You continue to prove your competence, {name}.  Hopefully this toxin will be enough to boost our plague to the levels that we need to.\n\nAt the very least it should help weaken the recipient and make them more susceptible to infection.", sourceObjectiveStatus = "unverified-source-field" }
quests[11169] = { id = 11169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Grimtotem Weapon", description = "During the last Grimtotem attack, I was wounded, but not before I managed to capture a curious totem our enemies were using against us.\n\nIt seemed to be emitting raw bolts of energy during the battle, but in all my experiments, I haven't managed to figure out how it works. I'll loan the totem to you if you agree to help me test it.\n\nThe watery areas surrounding the farm are home to pesky mottled drywallow crocolisks and drywallow daggermaws. Try fighting the crocolisks near the totem.", sourceObjective = "Apprentice Garion at Tabetha's Farm wants you to test the Captured Totem on 10 Mottled Drywallow Crocolisks or Drywallow Daggermaws.", progress = "Have you had any luck testing the totem?", completion = "<The apprentice listens as you describe your experiment.>\n\nA haze and some lightning? That's it? There's got to be more to the totem than just that! The Grimtotems aren't likely to bring something like this to the battlefield unless it has some kind of utility.", sourceObjectiveStatus = "unverified-source-field" }
quests[11170] = { id = 11170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test at Sea", description = "We've just received word of reinforcements coming to the aid of the Alliance forces.  Their timing couldn't be better!\n\nWe're in sore need of test subjects and these North Fleet reservists will do nicely!\n\nTake these plague vials with you and speak to Camille, the Bat Handler.  Tell her you need to commandeer a riding bat for a special assignment for us.\n\nOnce you're at sea, drop the vials on the reinforcement fleet.  I can't wait to see the results!", sourceObjective = "Speak to Bat Handler Camille and take a riding bat to intercept the Alliance reinforcements. Once above their fleet, use the Plague Vials to infect 16 North Fleet reservists.", completion = "Hmmphh.... the reports from the field are.... not encouraging!", sourceObjectiveStatus = "unverified-source-field" }
quests[11171] = { id = 11171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex Lord? Hah!", description = "Excellent! Everything's nearly ready for my grand entrance into Zul'Aman.\n\nYou've done a fine job, {name}. I've spoken with my crew and they're warming up to you nicely. I'd say you're very close to becoming a permanent member of the team. Only one thing remains for you to do - dispatch that 'Hex Lord' fellow.\n\nNothing to it, really. You stand up to this wretch and he'll likely just turn and run. Weaker, older trolls just add intimidating titles to their name to make up for their deficiencies, you see?", sourceObjective = "Budd Nedreck in Hatchet Hills wants you to kill Hex Lord Malacrass in Zul'Aman.", completion = "Finally! Now that the light work is done, I can at last make yet another mark on history. But first, there's one small matter to attend to - You....\n\nI'm afraid, {name}, that the time has come for me to let you go. I feel that your potential has been reached here, if not far exceeded.\n\nDon't feel bad, though. After all, it takes an exceptional type of individual to participate in such extraordinary events and not lose their wits. And look here, I have a little something for you to remember me by.", sourceObjectiveStatus = "unverified-source-field" }
quests[11172] = { id = 11172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Zeppelin Crash", description = "Not long ago, a goblin zeppelin crashed to the east. A representative of the Steamwheedle Cartel passed through here a few days ago.\n\nShe was looking for information about the zeppelin's cargo and it's pilot, Beezil, but none of us really got a good look at the crash. I doubt she'll be able to clean up after the wreck by herself, much less recover whatever cargo the vessel might have carried.\n\nIf you have time, you may want to check up on her out at Beezil's Wreck, due east of here, near the mountains.", sourceObjective = "Speak with Moxie Steelgrille at Beezil's Wreck.", completion = "So those hermit mages sent you? How can I be sure that I can trust you?\n\nI suppose I can use the help. There's not much here a mage would be interested in, anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[11173] = { id = 11173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Reagent Thief", description = "If there's one thing you can count on Apprentice Morlann to do, it's whine about reagents.\n\nNormally, I just ignore him, and it never works. This time, I'm going to try something different.\n\nMaybe if I replace the missing reagents before he notices, he'll leave me alone. The most common reagent we both use is marsh venom, which comes from the darkfang creepers and noxious shredders in the marsh north of the farm. If you bring me the venom, I'll replace it before Morlann notices it's gone.", sourceObjective = "Bring 6 vials of Marsh Venom to Apprentice Garion at Tabetha's Farm.", progress = "Did you get that venom? Morlann's going to discover that it's gone any moment now...", completion = "<Apprentice Garion inspects the venom.>\n\nThis is absolutely perfect! He'll never know the difference.", sourceObjectiveStatus = "unverified-source-field" }
quests[11174] = { id = 11174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "orrosion Prevention", description = "Just look at this area! It's swarming with oozes. If I don't find some way to keep them under control, they'll corrode the wreckage and the zeppelin's cargo!\n\nI can't go back empty-handed, {class}! Help me dissolve these oozes before they've digested everything!\n\nThis device, when powered, will concentrate energy on the slimes, causing them to explode. The zeppelin's fragmented power core should power the device. The one near the main crash works all the time, but the others flicker on and off.", sourceObjective = "Moxie Steelgrille wants you to dissolve 10 oozes and report back to her at Beezil's Wreck.", progress = "Did you make any progress against those oozes?", completion = "Well, it does look a little cleaner out there...\n\nI suppose it's time to get down to the business of salvaging this wreckage.", sourceObjectiveStatus = "unverified-source-field" }
quests[11175] = { id = 11175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Daughter", description = "Tell me, is it true? Did the explorers that went into Whisper Gulch go mad?\n\nMy daughter is the overseer of the Explorers' League that went north to some place called Steel Gate. With the horrible events that have befallen us, I fear for her safety.\n\nPlease, {class}, I am too old to make the journey. Her name is Irena. Will you go make certain that she is alright?", sourceObjective = "Old Man Stonemantle has asked you to find his daughter, Overseer Irena Stonemantle, at Steel Gate.", completion = "Grrr. I knew it! He's sooooo over-protective! This is just embarassing.\n\nNot that I'm not happy to see you... I am! We all are. We can use your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[11176] = { id = 11176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See to the Operations", description = "Our work out here is really just beginning. But now that we've brought these flying machines in from Westguard Keep, it should really pick up.\n\nThe problem is that we're lacking enough qualified pilots. And with things getting worse in the Rivenwood to the north, I'd like to get things wrapped up here quickly and then head back home.\n\nIf you can lend a hand, go have a chat with one of my chief archaeologists. You'll find them next to the flying machines on the north and south sides of the site.", sourceObjective = "Explorer Irena Stonemantle has asked you to speak with a Steel Gate Chief Archaeologist at Steel Gate.", completion = "Irena sent you over, did she? Good, we've got work for you then!", sourceObjectiveStatus = "unverified-source-field" }
quests[11177] = { id = 11177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Hermit of Swamplight Manor", description = "There's a fellow the locals know as \"Swamp Eye\" Jarl, who lives alone out in the swamp. Sometime ago he \"took over\" Swamplight Manor after the previous owners disappeared under mysterious circumstances.\n\nI like to send someone to check up on him every once in a while. He kind of reminds me of my grandfather, you know? Some say he's not quite right in the head.\n\nIf you're headed northwest on the road out of Theramore, you'll find Swamplight Manor in the Witch Hill area, before the road turns west.", sourceObjective = "Speak to \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Get off my lawn... unless, that is, you want to help old \"Swamp Eye\" with a little bit of cooking. Whad'ya say?", sourceObjectiveStatus = "unverified-source-field" }
quests[11178] = { id = 11178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Warlord", description = "As you examine the pulsating vial, your thoughts turn to the petulant little man outside Zul'Aman.\n\nYou can't wait to see Budd's expression when he sees this!", sourceObjective = "Bring the Blood of Zul'jin to Budd at his camp in the Ghostlands, outside Zul'Aman.", progress = "<Budd tries to mask his displeasure at your presence.>\n\nYou again....\n\nI don't know how else to say it - I'm simply too busy with my preparations to hold your hand any longer.\n\nTrust me, {name}, it's all for the best. Perhaps, by some miracle, you might eventually build a name for yourself.\n\nIf so, you'll be able to say that you got your start from the incomparable Budd Nedreck!", completion = "Th-the Blood of Zul'jin himself you say?\n\n<Gathering himself, Budd continues>\n\nWell, I appreciate the gesture, {class}, but I could've taken him down with ease. There's no way he was as fearsome as the legends say. These things have a way of being utterly overstated, as you'll learn in time. More likely, the pitiful old cretin was overcome with arthritis!\n\nAnyway, I suppose it was the least you could do as payment for the kindness I've shown you here.\n\nNow off with you - I must dispose of this vial!", sourceObjectiveStatus = "unverified-source-field" }
quests[11180] = { id = 11180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Haunting Witch Hill?", description = "I traveled out here to pay Jarl a visit at his new home and it's been a nonstop horror show ever since! There's something seriously wrong here and I can't be the only one who sees it...\n\nHave you seen the ghosts and corpses shambling about Witch Hill? I've a feeling that if anyone knows what happened here, it is them. Seek out these risen husks and risen spirits in the surrounding area, grant them rest through combat, and see what you can learn from them before this evil consumes Jarl!", sourceObjective = "Mordant Grimsby at Swamplight Manor wants you to gather information from 10 Risen Husks or Risen Spirits.", progress = "What have you learned from the spirits haunting this place?", completion = "<Mordant produces a small sheet of paper and a pen, beginning to scribble down notes on your findings.>\n\nFrom your findings, the spirits in this place must amount to everyone who ever lived on this land, not just the previous occupants.\n\nSomething has been corrupting and killing them. Those who follow don't learn the truth until it's too late. We have to put an end to this, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11181] = { id = 11181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witch's Bane", description = "In my years as an herbalist, I've often observed that nature will provide subtle cures to the most vexing of problems. I've read that hedge mages and witch doctors often use the smoke of an herb known as witchbane to draw evil from its hiding places.\n\nIf true, this would mean witchbane should be growing near the shallow waters of Witch Hill. You should be able to identify it by its broad leaves and reddish central stalk. Bring me any of the herb you can find, {name}. It may be our only hope.", sourceObjective = "Bring 9 sprigs of Witchbane to Mordant Grimsby at Swamplight Manor.", progress = "Were you able to gather any of the herb? We must work quickly, before whatever evil is behind this infestation consolidates its hold on this area.", completion = "<Mordant accepts the bunch of herbs from you.>\n\nThese match the description exactly! I prepared the torch while you were out. All that remains is to fasten the herbs to the end here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11182] = { id = 11182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Root Causes", description = "All things in nature seek a balance. It is only through the interference of those not in tune with that harmony that the balance is shifted.\n\nYou waste your efforts when you kill the whelps and drakes. The real culprits behind the expansion of these magically burning woods are the newly awakened vrykul and their master, Skeld Drakeson.\n\nIf it's blood on your hands that you seek, start with them. You will find their lair on the south side of the Ember Clutch.", sourceObjective = "Slay 5 Dragonflayer Handlers and Skeld Drakeson. If you manage to do so, return to an Ember Clutch Ancient in the Ember Clutch.", progress = "How fare your efforts against the meddlesome handlers, little one?", completion = "Unfortunate that one predator must be used to put down another, but that is the natural order of things.\n\nPerhaps now the proto-drakes and their whelps can go back to living peacefully. Somehow I doubt it with the reawakening of the vrykul.", sourceObjectiveStatus = "unverified-source-field" }
quests[11183] = { id = 11183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Witch Hill", description = "The torch is ready. Plant it at the end of the dock and be prepared to face whatever comes forth.\n\nI have no idea what the torch's smoke may reveal... if anything emerges at all. I must say, I have my doubts about this kind of folk magic, but we haven't time for anything else. For your sake and Jarl's, I wish you luck.", sourceObjective = "Mordant Grimsby at Swamplight Manor wants you to plant the torch at the end of the dock and defeat anything that appears.", progress = "Is it over?", completion = "It worked?\n\n<Mordant clears his throat.>\n\nI mean... it worked! Jarl and I are in your debt, {name}. Now the only remaining problem is my friend's taste in furniture, and I'm afraid that won't be solved as easily.", sourceObjectiveStatus = "unverified-source-field" }
quests[11184] = { id = 11184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ANTED: Goreclaw the Ravenous", description = "Travelers and Steamwheedle personnel working in the field are advised to avoid the Bloodfen Burrow to the west of town.\n\nThe area is overrun with raptors lead by the cruel and cunning Goreclaw the Ravenous, who has already killed at least two Steamwheedle engineers.\n\nDrazzit Dripvalve has authorized a generous reward to be paid to the individual who rids Mudsprocket of this menace.", sourceObjective = "Kill Goreclaw the Ravenous and report to Drazzit Dripvalve at Mudsprocket.", progress = "You look pretty satisfied with yourself. Come to claim the bounty on that monstrous raptor?", completion = "Thank goodness someone's finally taken me up on that offer. I was just thinking that I might need to triple the reward to get that stupid raptor killed, and our budget couldn't afford that!", sourceObjectiveStatus = "unverified-source-field" }
quests[11185] = { id = 11185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Apothecary's Letter", description = "Recovered from the body of a Forsaken apothecary, this letter contains alarming evidence of a close alliance between the Grimtotems and the new masters of Lordaeron.\n\n\"As a demonstration of good faith and a symbol of our newfound trust, we have dispatched Apothecary Cylla to aid you in battling our mutual enemy in the land of Kalimdor. None will stand before our combined might and determination.\"\n\nThis letter should be brought to the attention of the SI:7 agent at Tabetha's Farm, Andello Porter.", sourceObjective = "Bring the Sealed Letter to Andello Porter at Tabetha's Farm.", progress = "What is that you're carrying, {class}?", completion = "<Andello reads the letter, shocked at its contents.>\n\nWe've long had misgivings about the cooperation between the Horde and the Forsaken, and this only confirms those suspicions. With the backing for Forsaken magic and arms, the Grimtotems would become an even more fearsome enemy. The balance of power in Kalimdor could shift considerably.", sourceObjectiveStatus = "unverified-source-field" }
quests[11186] = { id = 11186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "igns of Treachery?", description = "Recovered from the body of a Forsaken apothecary, this letter hints at an underground correspondence between Undercity and the Grimtotem leadership.\n\n\"As a demonstration of good faith and a symbol of our newfound trust, we have dispatched Apothecary Cylla to aid you in battling our mutual enemy in the land of Kalimdor. None will stand before our combined might and determination.\"\n\nPerhaps Nazeer Bloodpike in Brackenwall Village will know how to handle this information.", sourceObjective = "Bring the Sealed Letter to Nazeer Bloodpike in Brackenwall Village.", progress = "What is that you're carrying, {class}?", completion = "If this is what it appears to be, the Forsaken have some explaining to do!\n\nThe antics of the Grimtotems have long tried the Warchief's patience. We have traditionally treated it as a matter to be settled among the tauren people, but this letter may change it.\n\nIt will take time to investigate these suspicions, but do not speak to anyone of what you have seen this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[11187] = { id = 11187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage-Lieutenant Malister", description = "THIS IS OUTRAGEOUS! Those proto-drakes are attacking the keep!\n\nBeasts such as that should have been scared off when you took care of their clutches and whelps.\n\nYou did take care of them, right?\n\n{name}, this calls for more direct action. Speak with my advisor, Mage-Lieutenant Malister. He'll provide you with the means to get at those infernal creatures.", sourceObjective = "Captain Adams has asked you to speak with his advisor, Mage-Lieutenant Malister, at Westguard Keep.", completion = "<Malister beckons you closer and speaks in whispered tones.>\n\nI was worried that something like this might happen. I tried to dissuade the captain from this course of action, but he is a dwarf of action with a definite outlook on how things should proceed.\n\nLet us speak of the options left to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[11188] = { id = 11188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two Wrongs...", description = "Now that we've riled up these Ember Clutch proto-drakes, they may be inclined to continue their attacks upon the keep. This will not do.\n\nI hate to compound one wrong with another, but in this case it would appear that we will have to destroy the creatures. A regrettable course of action, but one that we need to undertake regardless.\n\nTake my wand. I've been experimenting with increasing its range, but it doesn't pack much of a punch. However, what it will do is get a proto-drake's attention.", sourceObjective = "Mage-Lieutenant Malister at Westguard Keep has tasked you with the destruction of 3 Proto-Drakes.", completion = "<The mage-lieutenant sighs.>\n\nUnfortunate business to be certain. Well, what's done is done. With any luck the new whelps that grow to be drakes at Ember Clutch will not retain a memory of our shameful actions therein.\n\nAnd with a bit more luck, the boundaries of that magical forest will not continue to spread.\n\nHere, {name}, please take this pittance from the treasury for all of your troubles. It's the least that we can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11189] = { id = 11189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Time", description = "Hello there. Am I dead? I think I am, because I'm hovering over my body!\n\nOh, what an unfortunate turn of events. I was about to propose to Irena when the Scourge descended on us.\n\nI know that she's still alive... I can feel her in my heart.\n\n{class}, do you think you might safely get me to her? The Scourge can still see my ghost, and no doubt can do horrible things to me.\n\nI'd like to look upon her beautiful face one last time. You can tell her that I love her for me.", sourceObjective = "Escort the Ghost of Explorer Jaren safely to Explorer Irena Stonemantle at Steel Gate in the Howling Fjord.", sourceObjectiveStatus = "unverified-source-field" }
quests[11190] = { id = 11190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Size Does Not Fit All", description = "<Lad/Lass>, who's the genius that made our cannons a non-standard size? Now we have ta make special cannonballs ta shoot out o' the infernal contraptions!\n\nI would look kindly on ye if ye would go out and find the balls we've already shot. No doubt with the way these louts shoot they be all o'er the place ta the south and east.\n\n<The cannoneer spaces his hands apart to give you an idea of how big the cannonballs are.>\n\nThat would be faster than us making 'em from scratch fer a certainty.", sourceObjective = "Cannoneer Ely has tasked you with rounding up 10 Westguard Cannonballs and returning them to him at Westguard Keep.", progress = "We're runnin' dangerously low on rounds 'round here, {class}. Our enemies need poundin', especially Skorn!\n\nYa got more balls fer us?", completion = "Oh, bless ya, {name}, bless ya!\n\nJust set 'em down right where yer standin'. I'll have one o' the boys come load 'em up soon enough and we can stop worryin' 'bout runnin' out o' balls ta shoot at Skorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[11191] = { id = 11191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "his Old Lighthouse", description = "The old lighthouse out to the east hasn't worked for some time, but Babs Fizzletorque has gotten it into her head to get it working again.\n\nI don't know how she plans to do it by herself, but she claims that it'll make the movement of ships and goods into the docks smoother, so I can't really object. Drawing duty on the docks is really nothing to complain about when you could be on the front lines, you know?", sourceObjective = "Speak to Babs Fizzletorque at the lighthouse on the island east of Theramore.", completion = "Good. I can use all the help you can offer. My first priority is to get that lamp re-lit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11192] = { id = 11192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "hresher Oil", description = "The old log in the lighthouse indicates that the lamp was fueled with oil from the threshers that live along the coast here.\n\n<Babs wrinkles her nose at the mention of such outdated technology.>\n\nI suppose it's a practical, if inelegant solution. The log says that the oil taken from the youngest murk threshers works the best, and those live right underneath the docks of Theramore.\n\nIf you're up for it, would you help resupply the lighthouse with fuel?", sourceObjective = "Bring 4 containers of Thresher Oil to Babs Fizzletorque at the lighthouse near Theramore.", progress = "Were you able to get any of that thresher oil?", completion = "Well, I have my doubts, but this is the only solution available right now. Once we have it up and running, I'm sure there will be time to look at other ways to fuel the lamp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11193] = { id = 11193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "astardly Denizens of the Deep", description = "You know, it's amazing what you can find in that old lighthouse. After I lit the lamp, I noticed this book in one of the old trunks up there.\n\n<Babs holds up the book and reads the title dramatically.>\n\n\"Dastardly Denizens of the Deep!\"\n\nWhy, I think I might swoon if I ever saw one of these! I'm sure it's good for a laugh or two, but I simply don't have time for reading right now.\n\nYou know who might enjoy it, though... that fishmonger on the docks, \"Dirty\" Michael Crowe. He collects old books.", sourceObjective = "Bring Dastardly Denizens of the Deep to \"Dirty\" Michael Crowe on the Theramore docks.", progress = "What'll it be today? The snook is quite good.", completion = "Well, now, that was thoughtful o' Babs to send that over. I don't know if you've leafed through it or not, but there's a lot of truth to the tales in that book. Sailors didn't just make it all up, you know.", sourceObjectiveStatus = "unverified-source-field" }
quests[11194] = { id = 11194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "s it Real?", description = "Oh, I'm sure you and Babs had a good laugh over the outlandish descriptions and sketches in the book, but have you stopped to consider there might be some truth to the legends?\n\nIf you listen closely enough, I bet you can still hear sailors talk about Tethyr, the sea creature the book says lives right here! Of course, if you wanted to know for sure, you could always ask old Nat Pagle.\n\nHe's got a small fishing camp on a little island in Tidefury Cove, which is southwest across Dustwallow Bay.", sourceObjective = "Talk to Nat Pagle at Nat's Landing in Dustwallow Marsh.", completion = "So you want to know about sea monsters? Hmm... well, I'll make you a deal, but it's going to involve a lot of alcohol and some embarrassment on your part.", sourceObjectiveStatus = "unverified-source-field" }
quests[11195] = { id = 11195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playin' With Dolls", description = "I'm touched, {name}, an' dat be da truth. I'm not rememberin' the last time a {race} helped Zungam outta trouble.\n\nI snatched this from one of them savages when he was busy chainin' me up. It don't look like much, but if anyone can determine its worth, it be my good friend, Griftah!\n\nIf ya be makin' it outta here alive, it might be worth takin' this to him out in Shattrath City.", sourceObjective = "Take the Tattered Voodoo Doll to Griftah in Shattrath City.", progress = "Hey, {name}! I hear ya been workin' yer way into Budd's crew. Ya won't live to regret that move, friend, I can promise ya that.\n\nWhatcha got there, mon?", completion = "Hey now, where ya be gettin' this?\n\nNo, no, don't tell me - this be comin' from the Hex-Lord himself! It all be clear now. Strong mojo! The bearer of this relic, no matter how many disgraces he be sufferin', be always honored by his peers. Incredible!\n\n<As Griftah holds the doll in the air, a small, rusty charm falls from around its neck. The troll begins to discard it, but then turns toward you with a gleam in his eye.>\n\nI gots no coins right now, mon, but ya be welcome to this here...", sourceObjectiveStatus = "unverified-source-field" }
quests[11196] = { id = 11196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord of the Amani", description = "Da Amani been rebuildin' their forces and dey raised up a new warlord to lead dem, {name}. He be called Daakara da Invincible, but we be seein' whether he lives up to the name or not.\n\nYa must first defeat all his lieutenants to clear da way before ya can face this Daakara. Defeat him and put an end to da ambitions of da Zandalari and da Amani!", sourceObjective = "Defeat the new Amani warlord, Daakara.", progress = "Dis new warlord must fall before da Zandalari foothold here becomes permanent.", completion = "Victory be ours, {name}. Da Zandalari be fleein' and without da warlord's leadership, da Amani will soon be reduced to fighting among demselves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11198] = { id = 11198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ake Down Tethyr!", description = "Sea monster or no, we're not going to risk the safety of our shipping. I've ordered our best marksmen to prepare for a confrontation with this Tethyr. The artillerymen have augmented the dock's defenses with three mortars.\n\nI'm going to order the lighthouse's lamp illuminated. If Tethyr does attack, it will be your job to operate the mortars and take down the beast before it can kill all of the marksmen. I wouldn't stand in one place too long, though. Using the mortars is likely to draw its attention.", sourceObjective = "Major Mills at the Theramore docks wants you to defeat Tethyr.", completion = "Well done, {name}! I'll admit, when I caught my first glimpse of that beast, I had doubts about our ability to defend the docks, but you held together the defenders brilliantly!", sourceObjectiveStatus = "unverified-source-field" }
quests[11199] = { id = 11199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Scout Knowles", description = "{name}, now that those damnable proto-creatures have been dealt with, I've another task for you.\n\nOne of my scouts has reported back some suspicious activity by the Forsaken to the south. It looks like they're up to no good at the vrykul village known as Halgrind.\n\nI want you to personally take over the investigation down there. Speak with Scout Knowles to find out what he's uncovered and proceed from there.\n\nHis last reported position is at the Ember Spear Tower, just to the west of Halgrind.", sourceObjective = "Captain Adams has asked you to report to Scout Knowles at the Ember Spear Tower.", completion = "Oh good, help, and just in time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11200] = { id = 11200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ore than Coincidence", description = "We've gleaned as much as we can from the ruins of the inn. I'm concerned about where the investigation will lead us from here, but we must know the truth.\n\nBetween the hoofprints and the shield with Mosarn's mark, I'm lead to believe that the Grimtotems may have been involved. They've recently established a settlement in the swamp, Blackhoof Village to the northeast. Travel to Blackhoof Village and search for more arms of Mosarn's manufacture.", sourceObjective = "Krog at Brackenwall Village wants you to bring him 7 Blackhoof Armaments.", progress = "What did your search of Blackhoof Village reveal?", completion = "<Krog inspects the weapons and armor you've brought from Blackhoof Village.>\n\nThis is unmistakably the work of Mosarn. Questioning him further may draw too much attention, but we have a bit more freedom in dealing with the Grimtotems.", sourceObjectiveStatus = "unverified-source-field" }
quests[11201] = { id = 11201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Grimtotem Plot", description = "With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We've seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.\n\nBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems' plans.", sourceObjective = "Bring the Grimtotem Battle Plan to Krog at Brackenwall Village.", progress = "Were you able to find any trace of the orders?", completion = "<Krog reads over the battle plan.>\n\nThere's no doubt in my mind that the Grimtotems are moving against the humans. What I don't understand is what their intentions are toward us. The actions of the Grimtotems have caused tension within the Horde in the past, but the Warchief has always diffused it.", sourceObjectiveStatus = "unverified-source-field" }
quests[11202] = { id = 11202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Eternal Flame", description = "The Forsaken are up to no good and from what I can tell, those plague tanks of sludge are a big part of it.\n\nIf I may suggest, <sir/ma'am>, we should probably destroy them before they can get any more use out of the things. I took the liberty of preparing a bundle of torches from the Ember Clutch. These things have been burning for days!\n\nHere, I'm sure you can put them to better use than I in destroying those tanks.", sourceObjective = "Scout Knowles at the Ember Spear Tower has recommended that you use the Ever-burning Torches to destroy the four Plague Tanks surrounding Halgrind.", completion = "Nice!\n\nBut what's this about the stuff you found inside those tanks? Are you saying that the Forsaken are spraying a plague upon the vrykul down there?", sourceObjectiveStatus = "unverified-source-field" }
quests[11203] = { id = 11203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eek Out Tabetha", description = "The arms you captured in Blackhoof Village have not seen any combat beyond mere training exercises, which means the Grimtotems who destroyed the Shady Rest are still at large.\n\nTo the south, in the heart of the Quagmire, lives the witch Tabetha. Though she is a human, she has dealt honorably with us and trained some of our mages.\n\nAsk her for assistance in tracking down the band of Grimtotem responsible for burning the inn. The Alliance must not be allowed to think we were complicit in the attack.", sourceObjective = "Speak with Tabetha at her farm in the Quagmire.", completion = "<Tabetha smiles slightly.>\n\nKrog wishes me to scry for the Grimtotems, eh? Well, I have no need of magic in this case.\n\nIt seems we have a mutual enemy. The Grimtotems have built an outpost nearby and are a constant thorn in the side of me and my students.", sourceObjectiveStatus = "unverified-source-field" }
quests[11204] = { id = 11204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eturn to Krog", description = "I hope I've been helpful to you and I'm sorry I can't offer more information. My apprentices and I produce such a large volume of arms and armor that it's almost impossible to recall details about any individual piece.\n\nNot only do we outfit the braves defending tauren lands, but the Grimtotems have a particular fondness for my work. A seasoned warrior knows good work when he sees it.", sourceObjective = "Speak with Krog at Brackenwall Village.", completion = "He actually said that the Grimtotems are his biggest customers? Mosarn gave us more help than he knows. With this much pointing toward the Grimtotems, I think we just found our first suspects.", sourceObjectiveStatus = "unverified-source-field" }
quests[11205] = { id = 11205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "aze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", sourceObjective = "Burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post, then return to Tabetha at her farm.", progress = "Have you put that torch to good use?", completion = "The Grimtotems should have no trouble understanding our latest message.\n\nAs for you, your contact at Brackenwall Village will want to know of your success. I know the destruction of the Shady Rest Inn could be a source of tensions between the Horde and Alliance. If I encounter any investigators from Theramore, I will gladly tell them the Grimtotems acted on their own.", sourceObjectiveStatus = "unverified-source-field" }
quests[11206] = { id = 11206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ustice Dispensed", description = "I doubt the Grimtotems will give up their campaign to drive humans from the marsh, though I get the impression you probably don't mind that. At least we have dealt with the perpetrators of the crimes at the Shady Rest Inn.\n\nGo tell your leader that his vengeance has been sated.", sourceObjective = "Return to Krog at Brackenwall Village.", completion = "<Krog listens to your report.>\n\nI'm impressed, {name}. I would've thought that the Grimtotem criminals would've been more difficult to locate. \n\nTabetha's warnings have not fallen on deaf ears, but it is not my place to chastise the Grimtotems. I will, of course, mention it in my report to the Warchief. Do not speak of it to anyone until Thrall has dealt with the Grimtotems. You have done well in solving the mystery of the Shady Rest and sparing us from the suspicion of Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[11207] = { id = 11207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ecure the Cargo!", description = "This zeppelin was carrying six months' worth of supplies to us at Mudsprocket! Sure, they've been able to barter for some of what they need, but they won't hold out forever.\n\nI've been sent out here to recover what I can of the cargo, but the wreckage is scattered all over the marsh in this area. I'm sure a lot of the cargo didn't survive the crash, but are you willing to help me recover what we can?", sourceObjective = "Moxie Steelgrille at Beezil's Wreck wants you to recover 8 pieces of Zeppelin Cargo.", progress = "<Moxie looks frantic with worry.>\n\nDid the cargo survive? Did you find any of it?", completion = "Wow! You certainly found a lot more than I expected would be out there. I'm not sure how much Drazzit thought we were going to find out here, but he's going to have to be happy with this for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[11208] = { id = 11208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery for Drazzit", description = "Drazzit will expect to hear something from me soon, but I don't think the site is secure enough for me to leave. If you have time, would you be willing to take some of the salvaged cargo down to him at Mudsprocket?\n\nIf you haven't been there yet, it's a small settlement to the southwest of here, beyond the Stonemaul Ruins. You can take the road there from Tabetha's Farm, too. When you get to Mudsprocket, the guy you're looking for is Drazzit Dripvalve.", sourceObjective = "Take the Zeppelin Cargo to Drazzit Dripvalve at Mudsprocket.", progress = "Yes?", completion = "<Drazzit accepts the cargo from you.>\n\nI'm so hungry, I could eat a dragon! Thank goodness Moxie finally got some of that cargo down here. We've been reduced to playing dice against the ogre for whatever he's managed to kill on his hunting trips!", sourceObjectiveStatus = "unverified-source-field" }
quests[11209] = { id = 11209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "at's Bargain", description = "So you found a copy of Dastardly Denizens of the Deep, did you? Well, I can tell you from experience, it's all true. I've even seen a few of 'em with my own eyes.\n\nBut you want to know about Tethyr.  I said I'd make you a deal, so here's what I want you to do. I'm working on a new line of baits, but I haven't tested this one yet.\n\nJust take this paste -- yeah, it smells a little foul -- smear it on yourself, and swim over to that wrecked ship to the southwest. If you survive, let me know how it works!", sourceObjective = "Nat Pagle at Nat's Landing wants you to test his new fish bait.", progress = "Remember, the deal is \"don't come back until something bites you.\"", completion = "Not bad at all, but you know, I think I'd get a bath in as soon as possible, if I was you.\n\nNow, about your sea monster...\n\nHelp yourself to a brew or two in the meantime.", sourceObjectiveStatus = "unverified-source-field" }
quests[11210] = { id = 11210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "h, It's Real", description = "Yes, Tethyr is certainly real, and he lives in the waters off Theramore.\n\nHas a thing for bright lights. He's the reason they shut down the lighthouse in the first place, you know...\n\nAnd if you light it up again, he'll come right back. But no one in their right mind would do that.\n\nSo that must be your plan! It's been good sharing a drink with you, but don't blame ol' Nat if Tethyr REALLY turns you into fish bait. If you're going to do this, make sure you consult Major Mills at the Theramore docks.", sourceObjective = "Speak with Major Mills at the docks in Theramore.", completion = "<You recount your experiences with Nat Pagle, carefully omitting the portion about the 'bait test.'>\n\nWell, it sounds like we've got our work cut out for us. I'll make the preparations.", sourceObjectiveStatus = "unverified-source-field" }
quests[11211] = { id = 11211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help for Mudsprocket", description = "When that goblin... what's her name... Boxie, Foxy... Moxie, that's it! Anyway, when she came through here on her way to the zeppelin wreck, she said the town of Mudsprocket was having some problems.\n\nThat crashed zeppelin was bringing them fresh supplies. If you follow the road south from here, past the Stonemaul Ruins, you'll eventually come to Mudsprocket.\n\nWhy don't you check in with Drazzit Dripvalve down there and see if there's anything you can do to help?", sourceObjective = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "It's good of Tabetha to send you down here. I'd prevail upon her for some food until the wreckage from the zeppelin is taken care of, but I know she's got none to spare at the moment. If you're feeling adventurous, I've posted a bounty for the death of a particularly nasty raptor.", sourceObjectiveStatus = "unverified-source-field" }
quests[11212] = { id = 11212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabetha's Farm", description = "Deep in the heart of the swamp lives an old woman named Tabetha. We've never really known much about her, save that she's a good deal older than she appears. She's helped us from time to time and helped keep the peace here between the Horde and our forces.\n\nShe used to keep in regular contact, but we haven't received one lately.\n\nCould you check in with her when you have time? Just follow the road beyond North Point Tower, where it turns south and into the Quagmire. You can see her farm from the road.", sourceObjective = "Speak with Tabetha at her farm in the Quagmire.", completion = "It's good of Theramore to send someone. Your guard friend's suspicions were correct. We've got some new neighbors, and they aren't the kind you'd bring a casserole.", sourceObjectiveStatus = "unverified-source-field" }
quests[11213] = { id = 11213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Check Up on Tabetha", description = "A human woman named Tabetha lives on a small farm near the middle of the marsh. Ordinarily, I wouldn't associate with a human, but her help has proven useful at times.\n\nUnfortunately, she's been out of touch for quite some time now and I'm looking for someone to travel down to her farm to see if everything's all right.\n\nIf you follow the road south out of the village, then into the swamp's interior, you'll find her farm near the middle of the Quagmire.", sourceObjective = "Speak to Tabetha at her farm in the Quagmire.", completion = "It's fortunate Nazeer thought to send someone. We've got some new neighbors and they've been nothing but pests since they set up camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11214] = { id = 11214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ission to Mudsprocket", description = "The Steamwheedle Cartel has recently established a new outpost in the southern part of Dustwallow Marsh. It's called Mudsprocket, if I recall, and it's located on the main road south out of Tabetha's Farm and the Stonemaul Ruins.\n\nThis is an excellent opportunity for us to establish new trade contacts and Lady Jaina wants me to send a representative down there to establish contact. Would you be willing to go?", sourceObjective = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "So Theramore is interested in doing business? Well, that's not an offer I'd turn down. Supplies are pretty scarce here right now, so we need all the business contacts we can get!", sourceObjectiveStatus = "unverified-source-field" }
quests[11215] = { id = 11215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Mudsprocket", description = "The Steamwheedle Cartel's new outpost in the southern part of the marsh isn't faring so well. The zeppelin carrying supplies to Mudsprocket crashed, leaving them without vital tools, food, and medical supplies.\n\nFollow the road down south and into the marsh's interior. You'll pass by Tabetha's Farm and the Stonemaul Ruins before the road brings you to Mudsprocket. Offer any help you can provide to the town's leadership.", sourceObjective = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "I won't turn down any help! We're in the process of setting up here and trying to make the most of what we've got, until those supplies from the zeppelin arrive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11216] = { id = 11216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archmage Alturus", description = "I was sent here by my mentor to look for assistance, but unfortunately I'm not allowed outside of Lower City and the individuals that frequent this establishment tend to be less than helpful.\n\nYou do seem different, more like the adventurous type.  If you're interested in aiding our cause, speak to Archmage Alturus outside of Medivh's old dwelling, Karazhan.\n\nIn the meantime, I'm going to see about gaining access to the rest of the city.  One of our old associates is rumored to be here.", sourceObjective = "Speak to Archmage Alturus outside of Karazhan in Deadwind Pass.", completion = "I thank you for taking the time to come to our aid.  We've important work ahead of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[11217] = { id = 11217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "atch a Dragon by the Tail", description = "With the zeppelin crash delaying supplies, we've run out of medicines and bandages.\n\nWe're making use of what we can, but between all the insects, the injuries, and the enemies we're encountering here, I can barely keep up! I've found one herb that seems to help heal wounds and dull pain, but it, too, is in short supply.\n\nIt's called wyrmtail, and it's abundant in the Dragonmurk and Wyrmbog areas east of town. The plants themselves are made of coiled stalks, and seem to pulsate when you look at them.", sourceObjective = "Gizzix Grimegurgle at Mudsprocket wants you to bring him 8 Wyrmtail stalks.", progress = "Did you find any of the wyrmtail?", completion = "Thank you! This will help keep our guys going out in the field until Moxie returns with the rest of the supplies from the zeppelin crash.", sourceObjectiveStatus = "unverified-source-field" }
quests[11218] = { id = 11218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danger! Explosives!", description = "{name}, the captain's tasked me with a mission. I'd like you to help.\n\nA bunch of my fellow Explorers' League people went nuts digging up stuff in the Whisper Gulch just to the north. They're attacking anyone trying to get in!\n\nThe captain is only concerned with the ore for the keep. Lucky for us, I have just the thing to do the trick.\n\nGet in there, blow up the ore, and bring it back along with any gems you find. Running this place isn't cheap you know!\n\nI gotta warn you though, that ore is strange!", sourceObjective = "Use Steelring's Foolproof Dynamite to collect 6 Whisper Gulch Ore Fragments and 18 Whisper Gulch Gems. Then return them to Sapper Steelring at Westguard Keep.", progress = "Construction on this place seems to be a never-ending task. I just hope that you're able to get us what we need to continue.", completion = "The ore gave you a strange feeling? Maybe we won't use that stuff after all.\n\n<Steelring looks at the stuff and takes a step back, changing the subject.>\n\nThose gems look really nice! I wonder what I can get for them? Of course, there are always repairs, and new stuff to be made.\n\nYou know, I've really found working with you to be profitable. Take this... it's the least that I can do!", sourceObjectiveStatus = "unverified-source-field" }
quests[11219] = { id = 11219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Fires!", description = "The Horde's children need you, {name}.  The Headless Horseman, once a human paladin and now an insane fiend, has set fire to our village!  You must put out those fires!\n\nGrab a bucket and throw it onto the blaze, or toss it to an ally who is closer to the flames.  Extinguish all the fires and thwart the Headless Horseman!", sourceObjective = "The Masked Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Masked Orphan Matron in town.", progress = "The Horde's children need you!  Do not abandon them!", completion = "The fires are out!  You and your fire brigade were victorious!  Hah!\n\nThe Headless Horseman's attack has failed, but until he and his head are destroyed together, he will return.\n\nUntil then, however, let's take comfort in the safety you brought our children.  I am honored to have watched your brave work today.", sourceObjectiveStatus = "unverified-source-field" }
quests[11220] = { id = 11220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Headless Horseman", description = "Until the head of the Headless Horseman is destroyed, his rampage will not end.\n\nThe Horseman rests within the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades.  Go to his pumpkin shrine and speak these words:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nThis will rouse the fiend.  Destroy the head of the Horseman and he will plague us no longer.", sourceObjective = "Find the Headless Horseman's Pumpkin Shrine.", completion = "The origin of this shrine is unknown, but there is no doubt to whom it pays homage...", sourceObjectiveStatus = "unverified-source-field" }
quests[11221] = { id = 11221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reports from the Field", description = "Our mission in Northrend is to destroy Arthas.  The Alliance are but an obstacle that we'll crush wherever we find them.\n\nWe've managed to destroy their easternmost fleet; but the survivors have barricaded themselves on the Derelict Strand, south of here.\n\nOur forces should've overwhelmed their make-shift defenses long ago, but we underestimated their will to live.  Seek my officers in the field, Dark Ranger Lyana and Deathstalker Razael and get them to report on the situation.", sourceObjective = "Speak to Dark Ranger Lyana and Deathstalker Razael in the battlefield at the Bleeding Vale south of Vengeance Landing. Return to High Executor Anselm when you've completed this task.", progress = "Are you back with your report, {name}?", completion = "Cannons are holding us back?  I'll show them cannons.", sourceObjectiveStatus = "unverified-source-field" }
quests[11222] = { id = 11222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "roof of Treachery", description = "Although Onyxia has been exposed and removed from the court, the Defias who carried out her plan must be punished. Carry word to King Varian Wrynn in Stormwind castle that the Defias are the ones who carried out his kidnapping. I have little doubt that the king will mete out swift and terrible justice to those involved.\n\nI can use my magic to expedite your trip to Stormwind. Just speak to me when you're prepared to go, {name}.", sourceObjective = "Speak to King Varian Wrynn in Stormwind Keep.", completion = "<Highlord Bolvar listens while you deliver Jaina's message.>\n\nAre you certain? This is a very serious charge...", sourceObjectiveStatus = "unverified-source-field" }
quests[11223] = { id = 11223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eturn to Jaina", description = "I must make plans to destroy the remnants of the Defias. Please convey my thanks to Lady Jaina, back in Theramore. She has ever been a loyal friend and steadfast ally.\n\nGo to the Mage Quarter at the western end of the city and speak with Archmage Malin at the foot of the tower there. He will speed your return to Theramore.", sourceObjective = "Speak to Lady Jaina Proudmoore in Theramore.", completion = "That is excellent news, {name}! I was worried the highlord might question the veracity of our information, but I see now my concern was misplaced.\n\nYou are to be well rewarded for your efforts on behalf of Theramore and the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11224] = { id = 11224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send Them Packing", description = "I've heard rumors of bad happenings in the Whisper Gulch to the north. Most of the Explorers' League went down into that place, and some say they went mad with what they discovered.\n\nThat doesn't change the fact that they took most of our mules and equipment with them, though. I won't lose those mules!\n\nIf you find yourself in there, and happen across any of my mules, just get up close on them and threaten them with a raised hand. They'll spook and come home for sure.", sourceObjective = "Explorer Abigail has asked you to /raise your hand at 10 Abandoned Pack Mules and then return to her at Westguard Keep.", progress = "This is quite a blow to our efforts. I don't even want to know what they discovered down there.\n\nIt's enough to keep me awake at night just trying to imagine what it could be.", completion = "I'm indebted to you, {class}. At least with most of the mules and equipment recovered, we can hope to rebuild our numbers soon.\n\nPlease, take this.", sourceObjectiveStatus = "unverified-source-field" }
quests[11225] = { id = 11225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Witch Hill", description = "The marsh seems to have a strange effect on humans. Some grow mad simply by living here.\n\nAnyone who has ever settled at Swamplight Manor has gone mad in a spectacular way. The latest owner, one \"Swamp Eye\" Jarl, is already showing signs.\n\nI don't completely understand what's happening there, you'd have my thanks for looking into it.\n\nThe manor is at the eastern edge of the swamp. Trek east across Bluefen and past North Point Tower. The manor is in a haunted patch of land called Witch Hill.", sourceObjective = "Speak with \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Have you come here to spy on me? No?\n\nPerhaps you have an appreciation for fine cuisine, then? Good, you can help!", sourceObjectiveStatus = "unverified-source-field" }
quests[11227] = { id = 11227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Them Eat Crow", description = "The high executor wants me to use my dogs to sniff out enemy scouts, but I can tell you right now these plaguehounds aren't going anywhere until they're properly fed.\n\nIf our military doesn't understand that these beasts are picky enough to not eat the rubbish they've given me, then they can't expect them to be of any use in the field.\n\nYou seem to have some time on your hands, why don't you take one of these dogs out hunting for crows out west?  Their meat isn't very tasty to us, but my boys love it!", sourceObjective = "Pontius, the kennel keeper at Vengeance Landing, wants you to use the Plaguehound Cage to summon a Hungry Plaguehound and feed it Crow Meat from Fjord Crows west of Vengeance Landing.", progress = "Did you feed this little rascal here yet?", completion = "Did you hunt down some crows, boy?  Good boy, good boy!\n\nAh, these hounds remind me of my days raising purebreds in Tirisfal... those were good times!", sourceObjectiveStatus = "unverified-source-field" }
quests[11228] = { id = 11228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hell Has Frozen Over...", description = "Fordragon's got another thing coming if he thinks the group of green-gilled scrubs he sent to defend this port can hold out much longer.\n\n<Macalroy raises an eyebrow as he examines your equipment.>\n\nYou, however, might fare a bit better.\n\nThe importance of holding this port cannot be stated enough; and with those monsters flying overhead, the situation around here has gone from bad to worse.\n\nReport to Vice Admiral Keller just northwest of here and let him know that you're all out of bubble gum.", sourceObjective = "Speak with Vice Admiral Keller at Valgarde Port.", completion = "The dwarf speaks the truth. We can't afford to lose this port. It's one of two safe harbors that the Alliance has on this chunk of frozen hell - the other being a few hundred miles west of here on the coast of the Borean Tundra.", sourceObjectiveStatus = "unverified-source-field" }
quests[11229] = { id = 11229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Windrunner Fleet", description = "We have the Windrunner, the Queen's Reprisal and the Oblivion stationed just east of the Derelict Strand.  Send orders to the fleet's commander, Captain Harker, that they're to destroy the Alliance's cannons.\n\nSpeak to our bat handler, Camille, and ask for passage to the fleet's location.  Be quick, {name}, every minute we spend fighting the Alliance is a minute we could've spent fighting Arthas.", sourceObjective = "Speak to Bat Handler Camille at Vengeance Landing and obtain passage to the Windrunner. Report to Captain Harker aboard the ship.", completion = "I hope you're ready to fight, {name}.  The Queen's fleet needs you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11230] = { id = 11230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambushed!", description = "This should have been a walk in the park.  Their forces are hungry, injured and ill equipped.  Yet somehow, we walked right into their trap.\n\nWe approached these reefs from the south to gain cover and were immediately boarded by the Alliance dogs.\n\nI'm sorry to say, if you want our cannons to fire at anything, you're going to have to help us take our ships back.", sourceObjective = "Captain Harker aboard the Windrunner wants you to kill 15 North Fleet Marines.", progress = "What are you waiting for?  Kill the Alliance scum already!", completion = "Nice work paring those mongrels down to size.  My men will be able to clean up the rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[11231] = { id = 11231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Keys and Cages", description = "The captain may not care, but from the little we know, the vrykul are conducting heinous rites in some sort of 'awakening' ritual up north in Gjalerbron.\n\nThey're using living sacrifices to fuel their unholy rituals!\n\n{class}, you must put a stop to this! It matters not who or what is in those cages, they must be freed. I'd bet that the vrykul hold the keys.\n\nThe Light knows the last thing we need is more of those strange vrykul walking about, or worse yet, them wakening something even more evil!", sourceObjective = "Father Levariol has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to him at Westguard Keep when you manage to do so.", completion = "Bless you child! With your help, the Light shines even in the darkest of places.\n\nPlease, take this as just compensation for your good deeds. I shall see to the salvation of those you freed; at least, those truly within the Light, and the Alliance, who returned here to the keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[11232] = { id = 11232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guide Our Sights", description = "We should be able to kill our way back to our guns.  Unfortunately, visibility is less than desirable so you will have to mark our targets from the ground.\n\nTake these smoke flares with you and use them to mark the locations of the cannons along the northern wall in the Derelict Strand, west of here, where the Alliance are holding out.\n\nLet Lyana know as soon as the way is clear for the ground troops.  We can take care of ourselves over here.", sourceObjective = "Use the Smoke Flares at the location of the Alliance Cannons on the northern wall of the Derelict Strand. Report to Dark Ranger Lyana at the Bleeding Vale after you've completed this task.", progress = "The cannons, {name}.  Is someone going to take care of them?", completion = "Excellent.  I will signal our ground troops to make their move.", sourceObjectiveStatus = "unverified-source-field" }
quests[11233] = { id = 11233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landing the Killing Blow", description = "You've proven yourself in the field of battle, {name}.  You might very well have changed the tides in our favor.\n\nI've an important assignment for you now.  I'm not sure how much longer the weakness we've exposed is going to last, so we must use the element of surprise to our advantage.\n\nI want you to use the confusion created by our attack and go behind enemy lines to assassinate their leaders.  In order of rank, they are: Captain Olster, Lieutenant Celeyne and Sergeant Lorric.  Good luck, {class}.", sourceObjective = "Dark Ranger Lyana south of the Vengeance Landing wants you to kill Captain Olster, Lieutenant Celeyne, and Sergeant Lorric at the Derelict Strand.", progress = "Are the Alliance leaders dead, {name}?  Do not return until they are.", completion = "This marks undisputable victory for our forces.  Anselm will be most glad to hear about this.", sourceObjectiveStatus = "unverified-source-field" }
quests[11234] = { id = 11234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Anselm", description = "Let's send word back to old Anselm then.  Victory has come later than expected, but better late than never.  Tell him it will take our forces a few hours at most to finish off the stragglers here.\n\nGlory to the Banshee Queen!", sourceObjective = "Report back to High Executor Anselm at Vengeance Landing in Howling Fjord.", completion = "It was about time.  The Alliance has been a thorn in our side for a long time now.\n\nThere's no time to celebrate, however.  Look to the west, it appears we have visitors.", sourceObjectiveStatus = "unverified-source-field" }
quests[11235] = { id = 11235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing With Gjalerbron", description = "And now we have a different problem. My scouts that have lived to return have informed me that the vrykul are up to no good at their main fortress to the north.\n\nThey call the place Gjalerbron, though you'd pronounce the 'Gj' as if it were an 'Sh'. Odd creatures.\n\nBut that's not important; what is, is that you get up there and put an end to the lives of as many of those creatures as you can while trying to figure out what they're up to.\n\nI know that I can count on you, {name}.", sourceObjective = "Captain Adams has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Westguard Keep.", completion = "Good work, {name}, and good riddance.\n\nBut, what you say about that place troubles me still, and I think our culling is not quite at an end!", sourceObjectiveStatus = "unverified-source-field" }
quests[11236] = { id = 11236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necro Overlord Mezhen", description = "The Scourge are at Gjalerbron and they have necromancers with them! They must be working to bring the vrykul into Arthas' fold.\n\nI want the leader of these necrolords eliminated!\n\nDo whatever it takes, {name}, but see to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized.\n\nI will not see the vrykul successfully allied with the Scourge!\n\nLook for Mezhen on the platform in the rear right section of Gjalerbron.", sourceObjective = "Kill Necro Overlord Mezhen. Then, return to Captain Adams at Westguard Keep.", completion = "<The captain breathes a sigh of relief.>\n\nWell, that should take some of the pressure off of us.\n\n{name}, time and again you have proven yourself invaluable to Westguard Keep and the Alliance at large. Pick something from the treasury, boy! It's the least we can do!", sourceObjectiveStatus = "unverified-source-field" }
quests[11237] = { id = 11237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gjalerbron Attack Plans", description = "These plans detail an imminent attack upon Westguard Keep. It would appear that the frost wyrm, Glacion, who circles overhead is to be used for the offensive.\n\nSurely Mage-Lieutenant Malister would be of some assistance in this matter. Deliver the plans to him at the keep to the south.", sourceObjective = "Deliver the Gjalerbron Attack Plans to Mage-Lieutenant Malister at Westguard Keep.", progress = "What?! Plans for an attack upon the keep?\n\nA FROST WYRM?!!!", completion = "{name}, we can't let this come to pass!", sourceObjectiveStatus = "unverified-source-field" }
quests[11238] = { id = 11238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frost Wyrm and its Master", description = "You were right to bring this to me, {name}. You must venture to Gjalerbron and slay that wyrm and its master, Wyrmcaller Vile!\n\nEven now, as we speak here, the frost wyrm may be on its way.\n\nHowever, if I'm reading these plans correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!\n\nAnd {name}, please bring me the horn. We wouldn't want it falling back into the wrong hands.", sourceObjective = "Slay Wyrmcaller Vile and use the Wyrmcaller's Horn to call down and slay Glacion. Then, return with the horn to Mage-Lieutenant Malister at Westguard Keep.", progress = "Is the attack averted? Are the frost wyrm and its master destroyed?\n\nDid you retrieve the horn?", completion = "Wow, that horn is cold!\n\nOnce again you've saved Westguard Keep from certain doom. What a curious man you are, {name}. If only there were more of you.\n\nWell, this certainly calls for a reward. Which do you prefer?", sourceObjectiveStatus = "unverified-source-field" }
quests[11239] = { id = 11239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service to the Light", description = "Your service has been exemplary, {name}, but there is something that is troubling me: the Scourge.\n\nThe Light cannot abide their presence, and neither shall we. I hope that it is not asking you too much, but I would have you return north to Gjalerbron and crush the unholy Scourge in that vile lair! Be sure to check for them in the Waking Halls beneath Gjalerbron as well.\n\nPurification is the key to salvation, my child. Make us proud!", sourceObjective = "Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Father Levariol at Westguard Keep of your success.", completion = "<The priest quietly mouths a benediction for you.>\n\nBless you, {name}, you have answered my prayers. Stand proudly in the Light, chin held high with the knowledge that your actions were most holy!\n\nI'm certain that the church's coffers can yield up something of use to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11240] = { id = 11240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leader of the Deranged", description = "So, I hate to say it, pal, but while you were out, the captain took a keener interest in that place.\n\nLooks like he wants my old Explorers' League boss in there dead. My guess would be that we're gearing up for an offensive to clear out the rest of them, and the captain wants their head lopped off, as it were.\n\nDo me a favor? Head back into Whisper Gulch and put an end to Squeeg Idolhunter. From what I remember, my guess would be that he's in the cave in the northwest corner.", sourceObjective = "Slay Squeeg Idolhunter and then report back to Sapper Steelring at Westguard Keep.", completion = "<The sapper grumbles as if he wishes that you hadn't succeeded.>\n\nThe captain will be pleased to hear of your success.\n\nYou know, since you've been such a good sport in dealing with this Whisper Gulch business, why don't you take your pick of one of these?", sourceObjectiveStatus = "unverified-source-field" }
quests[11241] = { id = 11241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trail of Fire", description = "Thanks for bailing me out of this mess, {name}.  I was not looking forward to what these Alliance scumbags had in store for me.\n\nLet's get out of here and see if we can get back at them somehow.  Is that a campfire over there?", sourceObjective = "Escort Apothecary Hanes out of the Derelict Strand. Report to Apothecary Lysander at Vengeance Landing in Howling Fjord when you've completed this task.", completion = "Apothecary Hanes is alive?  You burned the Alliance supplies to the ground?  He must've gotten a real kick out of that.\n\nAt any rate, the Royal Apothecary Society is in your debt, {name}.  We thank you from the bottom of our black, black hearts.", sourceObjectiveStatus = "unverified-source-field" }
quests[11242] = { id = 11242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.", sourceObjective = "Take the Tome of Thomas Thomson to the Costumed Orphan Matron in Goldshire, Kharanos or Azure Watch.", progress = "You have something for me, good {name}?", completion = "What is this?  The tome of Thomas Thomson?  But that is the name of the Horseman before he was cursed!  Does this mean that he is finally free?  Does this mean he will no longer torment the good people of Azeroth?\n\nWhat a joyous day!  {name}, your feat will live long with us.  The children, and their children, will sing your name!", sourceObjectiveStatus = "unverified-source-field" }
quests[11243] = { id = 11243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If Valgarde Falls...", description = "If Valgarde falls, our primary supply line into Northrend will cease to exist. From there it'll only be a matter of time before we're all servants of the Lich King. Now I don't know about you, but I've got a wife and three kids back in Elwynn and I'll be damned if I'll go down without a fight.\n\nThe situation here is critical and we can use all the manpower you're able to muster. Get to the front gate and help the guards defend the city against the invading monsters!", sourceObjective = "Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to slay 12 Dragonflayer Invaders or Dragonflayer Worgs.", progress = "The fate of the world may very well rest with us.", completion = "You gave our defenders the extra support they needed, {name}. Morale is higher than ever now, thanks to you. I think they'll be able to handle the remaining onslaught on their own. I've got bigger plans for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[11244] = { id = 11244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescuing the Rescuers", description = "We'd been here for a month when those malformed giants appeared out of thin air. We were ill-prepared for any sort of attack and paid dearly for our complacency. An entire archaeology team was lost and several townsfolk were abducted and taken to the ruins. We've been on the defensive ever since.\n\nTo make matters worse, the scouts we sent to rescue our people have been harpooned by the vrykul and left for dead in the forest directly north of Valgarde. Dislodge those harpoons and free our scouts!", sourceObjective = "Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 8 Valgarde Scouts that have been impaled and left for dead.", progress = "Find those scouts!", completion = "What the vrykul did to our scouts was a gruesome display of savagery. It was a scare tactic, meant to weaken our resolve... to send us running in fear for our lives.\n\nIt failed.\n\nWe are going to show those monsters what it means to wage war against the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[11245] = { id = 11245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Towers of Certain Doom", description = "<Sir/Ma'am>, as we move through Skorn, we have to bring down those towers!\n\nIf you have a look at them, you'll notice that their tops are lined with casters. Getting too close to them would mean certain doom for us!\n\nHowever, we do have it within our means to call in cannon volleys from Westguard Keep. To do so, we need to get close enough so that you can lob a smoke flare atop of them.\n\nJust don't get too close!", sourceObjective = "The Westguard Sergeant has informed you that using the Sergeant's Flare to target all four of the towers at Skorn for cannon volleys would be advisable.", progress = "Getting too close to those towers is certain death as long as those casters are up there.", completion = "Excellent targeting, sir! I'll have to remember to buy a round for the cannoneers back at the keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[11246] = { id = 11246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gruesome, But Necessary", description = "We've had reports that these vrykul can rise from the dead; not unlike the Scourge, but a different kind of undeath.\n\nLet's not take any chances.\n\nHere, take my machete. As we move through this place, you'll need to carve up the remains of the vrykul that we take down. I'd do it, but I have a sensitive stomach.\n\n<The sergeant smirks.>\n\nI spent all morning sharpening it, so it should do the job.", sourceObjective = "The Westguard Sergeant has asked you to use The Sergeant's Machete to dismember 20 Vrykul of the Winterskorn tribe at Skorn.", completion = "Well, sir, I have to say that you went about that particular business with a bit of zeal.\n\n<The sergeant looks at you warily.>\n\nAnyway, if you don't mind, I'll be taking my machete back now. It looks dull and we wouldn't want you to accidentally slip and carve me up, too.", sourceObjectiveStatus = "unverified-source-field" }
quests[11247] = { id = 11247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn Skorn, Burn!", description = "Captain Adams gave me strict instructions to make sure that a good deal of infrastructure damage was inflicted on this site.\n\nHowever, since you're in charge out here, that's at your discretion, <sir/ma'am>.\n\nMay I suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn? All we have to do is get inside each and throw this torch.", sourceObjective = "The Westguard Sergeant has orders that you should use the Sergeant's Torch to set fire to the Northeast and Northwest Longhouses and the Barracks at Skorn.", progress = "May I suggest that when we set the buildings ablaze, we not tarry too long inside of them?", completion = "Very good, sir. That couldn't have been done without your help.\n\nI'm sure that the captain will be pleased with my report on the matter once we're done here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11248] = { id = 11248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Skornful Wrath", description = "{name}, I must now ask you to undertake an operation so hazardous, so deadly, that only you can see it through.\n\nThe vrykul fortress, Skorn, sits on our eastern border. My scouts inform me that those 'giants' are poised to strike us, and with my forces scattered all over the fjord, I don't have the men to take the place by force.\n\nInstead, you're going to use your cunning. I've sent a sergeant ahead with the details. Show this command insignia at Skorn and he'll reveal himself and follow your orders.", sourceObjective = "Captain Adams has asked you to use the Westguard Command Insignia at Skorn, and then to speak with the Westguard Sergeant.\n\nProvided item:", completion = "A pleasure to meet you, sir! I look forward to working with you.\n\nSpeaking of which, we have a great deal to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11249] = { id = 11249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Ascension!", description = "This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual.\n\nA vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture's background.\n\nA tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.", sourceObjective = "Present the Vrykul Scroll of Ascension near the Thane's Pyre to call him out and slay him. Afterward, due to the nature of the ritual, you're sure that Father Levariol at Westguard Keep will be interested in seeing the scroll.", progress = "Yes? How may I help you, my child?", completion = "Yes, my son, that is ominous-looking, and you obviously had the right of it.\n\nThank you for bringing this scroll to me. I am very keen to study its implications. If I were to hazard a guess, I would say that these vrykul have a way to transcend death; at least those that are worthy.\n\nBy defeating the Winterskorn thane, you proved him unworthy. The Light only knows what he would have become, and what terror he might have rained down upon us, had you not slain him.", sourceObjectiveStatus = "unverified-source-field" }
quests[11250] = { id = 11250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Hail the Conqueror of Skorn!", description = "We -- well, you -- have done everything that we were sent here to accomplish <sir/ma'am>. I must say that it's been a pleasure taking orders from such a fine, young {race}.\n\nThe captain is sure to want to hear of your success, but if you decide to stay out here for whatever reason, I am at your disposal.", sourceObjective = "Return the Westguard Command Insignia to Captain Adams at Westguard Keep.", progress = "I gather that since you're here, Skorn is no more?", completion = "That's unbelievably good news! I knew that you could pull it off, {name}!\n\nAt least someone around here can produce results!\n\nWell, this calls for a reward. Go ahead, take your pick; the treasury is open to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11251] = { id = 11251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Legs", description = "It's come at great cost, but we've completed our inspection of the site.\n\nThe news isn't good. Nearly everyone has been slain or captured. Only a few veteran guards remain unaccounted for.\n\nThe scouts have done all we can here. You must pick up where we've left off.\n\nSounds of a skirmish are coming from up the hill to the northeast. Have a look, {class}. We can only hope there are some who have survived, and that they may have some intel we can use against this enemy.", sourceObjective = "Scout Valory wants you to investigate the sounds of battle coming from the northeast of Wyrmskull Village.", completion = "Late though ye may be, it's good to see a friendly face.\n\nNow stop standin' around with yer thumb up yer nose. there's work to be done!", sourceObjectiveStatus = "unverified-source-field" }
quests[11252] = { id = 11252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Utgarde!", description = "Listen up, youngster. I've put down me share of these creatures - and your share too fer that matter. Here be what ya need to know....\n\nThe vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple.\n\nThere's one they esteem though, goes by the name of Ingvar. I dunno why they be seekin' his praise, but bring him down and you'll deal a mighty blow to their spirit.\n\nThen, perhaps, we'll have a chance....", sourceObjective = "Defender Mordun has tasked you with the execution of Ingvar the Plunderer who resides deep in Utgarde.\n\nYou are then to bring his head to Vice Admiral Keller.", progress = "Good to see you're well, {name}.\n\nWe've had about as many casualties as we can handle.", completion = "Outstanding!\n\nThis could be the turn of luck we've all been hoping for.\n\nWell done, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11253] = { id = 11253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniff Out the Enemy", description = "Now that this rascal's belly's full, maybe he will be more willing to cooperate.  Here's his leash, just come get him from his cage whenever you're ready to take him.\n\nI don't know what Anselm expects you to find, but look for clues wherever it is that the dog takes you.", sourceObjective = "Use the Plaguehound Leash near the plaguehound cages at Vengeance Landing and look for clues at the location you're led to by the Plaguehound Tracker.\n\nProvided item:", completion = "This scaly scroll is covered in stark painted images.  You've a feeling this is the sort of thing the kennel keeper had in mind when he asked you to look for clues.", sourceObjectiveStatus = "unverified-source-field" }
quests[11254] = { id = 11254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragonskin Map", description = "Upon closer inspection, the scroll appears to be a heavily-illustrated map of the fjord.  The location of various villages are depicted in what seem to be tribal symbols.\n\nThe location of Vengeance Landing is marked with a disproportionately large skull.\n\nThis map will almost certainly be of military value to High Executor Anselm.", sourceObjective = "Bring the Dragonskin Map to High Executor Anselm in Vengeance Landing.", progress = "You've something to show me, {class}?", completion = "<The high executor looks at the map intently, occasionally looking up at landmarks around the Fjord.>\n\nHere's the eastern coastline over here.  The Dragonflayer and Winterskorn villages are here and here... and this must be us over here, marked for death.", sourceObjectiveStatus = "unverified-source-field" }
quests[11255] = { id = 11255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners of Wyrmskull", description = "This battle is far from over, {name}. If our people are still alive inside that village, someone has to go and get 'em.\n\n<Vice Admiral Keller nods at you.>\n\nHead north and enter Wyrmskull Village. Once there, look for our people. If they are imprisoned you'll need to find a way to break them out.\n\nMaybe they'll have some more information about what it is that we're actually fighting.", sourceObjective = "Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 3 Captured Valgarde Prisoners.", completion = "Those soldiers you rescued had a good bit of information for us. These monsters call themselves 'vrykul.' The tribe that's taken up residence in Wyrmskull Village is led by a mystic named Yanis who himself is an underling of another vrykul known as Ingvar the Plunderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[11256] = { id = 11256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skorn Must Fall!", description = "{name}, the vrykul fortress, Skorn, sits to the south. Its strange giants have recently awakened and have begun to spread, attacking us wherever they can.\n\nMy scouts inform me that they are poised to strike at us here, but I do not have the strength to repel such a force. Instead, we will prepare to leave north to less dangerous lands.\n\nI ask that you use your cunning to buy us time. I've sent a brave ahead with the details. Show this emblem at Skorn and he'll reveal himself and do all he can to aid you.", sourceObjective = "Chieftain Ashtotem has asked you to use the Winterhoof Emblem at Skorn, and then to speak with the Winterhoof Brave.\n\nProvided item:", completion = "It will be interesting to learn about your people, {class}, while fighting alongside you.\n\nShall we proceed?", sourceObjectiveStatus = "unverified-source-field" }
quests[11257] = { id = 11257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gruesome, But Necessary", description = "Our elders say that these vrykul may be able to rise from the dead; not unlike the walking dead you call the Scourge, but a different kind of undeath.\n\nWe should not take any chances.\n\nHere, take my machete. As we move through this place, carve up the remains of the vrykul that we slay.\n\nI spent the morning sharpening it, so it should cleave even through their thick bones.", sourceObjective = "The Winterhoof Brave has asked you to use The Brave's Machete to dismember 20 Vrykul of the Winterskorn tribe at Skorn.", progress = "These vrykul have strange customs, would you not agree, {name}?", completion = "Have you done that before? Your skill with my machete seemed practiced.\n\n<The brave looks at you warily.>\n\nI'll take it back from you now, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11258] = { id = 11258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn Skorn, Burn!", description = "Chieftain Ashtotem ordered me to destroy many buildings here.\n\nHowever, you are in charge, so it falls to your hands, {name}.\n\nI suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn. All we have to do is get inside each and set them ablaze with this torch.", sourceObjective = "The Winterhoof Brave suggests that you use the Brave's Torch to set fire to the Northeast and Northwest Longhouses and the Barracks at Skorn.", progress = "I suggest that when we set the buildings ablaze, we not stay inside of them. The fire spirit will not spare us in its thirst to destroy.", completion = "<The brave nods at you in clear approval of your handling of the torch>\n\nLet these vrykul feel the heat of the land. Let them know the fear they would instill in others!", sourceObjectiveStatus = "unverified-source-field" }
quests[11259] = { id = 11259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Towers of Certain Doom", description = "As we move through Skorn, we must destroy the towers.\n\nIf you have a look at them, you'll notice that their tops are lined with casters. Getting too close to them would mean certain doom.\n\nHowever, we can call in wind rider air strikes from Camp Winterhoof. To do so, we need to get close enough so that you can lob a smoke flare atop of them.\n\nJust don't get too close.", sourceObjective = "The Winterhoof Brave has informed you that using the Brave's Flare to target all four of the towers at Skorn for air strikes would be advisable.", progress = "Getting too close to those towers is certain death as long as those casters are up there.", completion = "You have a strong arm, {name}.\n\nIt looks as if those wind riders finally made themselves useful instead of just standing around and drinking all day.", sourceObjectiveStatus = "unverified-source-field" }
quests[11260] = { id = 11260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Ascension!", description = "This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual.\n\nA vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture's background.\n\nA tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.", sourceObjective = "Present the Vrykul Scroll of Ascension near the Thane's Pyre to call him out and slay him. Afterward, due to the nature of the ritual, you're sure that Greatmother Ankha at Camp Winterhoof will be interested in seeing the scroll.", progress = "Yes? How may I help you, child?", completion = "Yes, that is ominous-looking, and you obviously had the right of it.\n\nThank you for bringing this scroll to me. I will study its implications. If I were to hazard a guess, I would say that these vrykul have a way to transcend death; at least those that are worthy.\n\nBy defeating the Winterskorn thane, you proved him unworthy. Who knows what he would have become, and what terror he might have rained down upon us, had you not slain him?", sourceObjectiveStatus = "unverified-source-field" }
quests[11261] = { id = 11261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conqueror of Skorn!", description = "You have done everything that we were sent here to do, {class}. I must admit that you fight well. Your people are not as strange as I first thought.\n\nChieftain Ashtotem is certain to want to hear of your success, but if you decide to stay out here for whatever reason, I will continue to fight at your side.", sourceObjective = "Return the Winterhoof Token to Chieftain Ashtotem at Camp Winterhoof.", progress = "What news do you bring of Skorn, {name}?", completion = "That is good news indeed! You have given us some breathing room to further our preparations for leaving.\n\nPlease, take one of these as a sign of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[11262] = { id = 11262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingvar Must Die!", description = "Of our entire recon party, only I remain.\n\nThese vrykul are relentless fighters. Given their numbers and their savage tactics, our only hope is to bring down their leader and pray it brings chaos to their ranks.\n\nIngvar is his name. Bring me his head!", sourceObjective = "Dark Ranger Marrah has asked you to kill Ingvar the Plunderer inside Utgarde Keep.", progress = "This is just the tip of the iceberg, so to speak.", completion = "Excellent work, {name}. With their leader removed, our efforts against these vrykul should be more successful.\n\nService such as this cannot go unrewarded!", sourceObjectiveStatus = "unverified-source-field" }
quests[11263] = { id = 11263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing With Gjalerbron", description = "My longrunners that have lived to return have informed me that the vrykul have awakened at their main fortress to the west.\n\nIt is a forbidden place known as Gjalerbron. The longrunners tell me that the vrykul are performing strange rituals.\n\nWe cannot allow this to continue.\n\nAre you willing to continue to assist us? Will you kill the vrykul at Gjalerbron before they finish whatever they are doing and attack us here?", sourceObjective = "Chieftain Ashtotem has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Camp Winterhoof.", completion = "You have my thanks, {name}. I know that you do not have any duty to me or my people.\n\nWhat you say about that place troubles me still, and I sense that our culling is not quite at an end.", sourceObjectiveStatus = "unverified-source-field" }
quests[11264] = { id = 11264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necro Overlord Mezhen", description = "The dead ones are at Gjalerbron and they have necromancers with them?\n\nWe must eliminate the leader of these necrolords.\n\nDo whatever it takes, {name}, but see to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized.\n\nWe cannot afford to see the vrykul successful in whatever they are doing with these undead creatures!\n\nLook for Mezhen on the platform in the rear right section of Gjalerbron.", sourceObjective = "Kill Necro Overlord Mezhen. Then, return to Chieftain Ashtotem at Camp Winterhoof.", progress = "Are you sure that you killed Mezhen and his necrolords, {race}?", completion = "<Chieftain Ashtotem breathes a sigh of relief.>\n\nThat should take some of the pressure off.\n\n{name}, time and again you have proven your value to the taunka of Camp Winterhoof. Please, choose something from our bounty. I insist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11265] = { id = 11265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Keys and Cages", description = "From the little we know, the vrykul are conducting unnatural rites in an 'awakening' ritual to the west in Gjalerbron.\n\nThey're using living sacrifices to fuel their rituals.\n\n{name}, you must stop this. It matters not who or what is in those cages, they must be freed. I would guess that the vrykul hold the keys.\n\nThe last thing we need is more of those strange vrykul threatening us, or worse, them wakening something even more evil....", sourceObjective = "Greatmother Ankha has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to her at Camp Winterhoof when you manage to do so.", completion = "A great stone is lifted from my shoulders to hear of your success. And I smile to know that some you freed were taunka.\n\nPlease, take this as a gift for what you have done. I shall see to the health of those you freed.", sourceObjectiveStatus = "unverified-source-field" }
quests[11266] = { id = 11266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gjalerbron Attack Plans", description = "These plans detail an imminent attack upon Camp Winterhoof. It would appear that the frost wyrm, Glacion, who circles overhead, is to be used for the offensive.\n\nSurely Celea Frozenmane would be of some assistance in this matter. Deliver the plans to her at the camp to the east.", sourceObjective = "Deliver the Gjalerbron Attack Plans to Celea Frozenmane at Camp Winterhoof.", progress = "What?! Plans for an attack upon our camp?\n\nFROM A GREAT WYRM IN THE SKY?!!!", completion = "{name}, we cannot let this come to pass!", sourceObjectiveStatus = "unverified-source-field" }
quests[11267] = { id = 11267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frost Wyrm and its Master", description = "Your instincts were right to bring this to me, but my wind riders cannot fight a dragon. You must venture west to Gjalerbron and slay the frost wyrm and its master, Wyrmcaller Vile!\n\nEven now it may be on its way!\n\nIf I'm reading these plans correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!\n\nAnd {name}, bring me the horn. We wouldn't want it falling back into the wrong hands!", sourceObjective = "Slay Wyrmcaller Vile and use the Wyrmcaller's Horn to call down and slay Glacion. Then, return with the horn to Celea Frozenmane at Camp Winterhoof.", progress = "Is the attack averted? Is the great death wyrm and its master destroyed?\n\nDid you retrieve the horn?", completion = "This horn is as cold as the land... perhaps even colder!\n\nYou have saved Camp Winterhoof from certain doom, not that we'll be staying here much longer. What a curious man you are, {name}. Perhaps you {race}-types from over the ocean are not so bad after all.\n\nThis calls for a reward. Which do you prefer?", sourceObjectiveStatus = "unverified-source-field" }
quests[11268] = { id = 11268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Walking Dead", description = "Your assistance to us has been tremendous, {name}, but there is something that is troubling me: these so-called Scourge.\n\nThe spirits of the land and air, the waters and the fire below the world, would not abide their presence, but seem to do nothing about them. We will see to it that they are dealt with!\n\nPerhaps it is asking too much, but I would have you return west to Gjalerbron and destroy the unnatural Scourge in that vile lair. Be sure to check in the Waking Halls below Gjalerbron as well!", sourceObjective = "Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Greatmother Ankha at Camp Winterhoof of your success.", completion = "<The greatmother nods her approval of your actions.>\n\nThank you, {name}, you have done what is right and you have bought us a little more time to finish our preparations for leaving. We will soon make the journey north.\n\nI am too old; when we go, I will not be able to carry everything with me. Would you like to take one of these?", sourceObjectiveStatus = "unverified-source-field" }
quests[11269] = { id = 11269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to the Wire", description = "The vanguard of the Alliance force will be arriving within days. The soldiers will be expecting their winter gear to be prepared, but I've still got more cloaks to make.\n\nI've been using spotted hippogryph down for the cloaks' linings, but my stock won't last!\n\nYou've got to help me, {name}. Captain Adams will have my hide if those cloaks aren't ready in time! Bring me all the down you can find out there. It's dropped to the ground by molting hippogryphs flying over the wilderness around the fort.", sourceObjective = "Gil Grisert wants you to bring him 10 clumps of Spotted Hippogryph Down.", progress = "Have you brought any of that down? I could really use it...", completion = "Thank goodness! This should be enough to finish the order in time. Of course, I won't sleep until the troops arrive, but that's far better than risking Captain Adams' wrath.\n\nI've heard the stories they tell about him!", sourceObjectiveStatus = "unverified-source-field" }
quests[11270] = { id = 11270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War is Hell", description = "We're slowly finishing off the remnants of Stormwind's North Fleet stationed on this coast.  The bodies to the west are a testament to how brutal this confrontation has been.\n\nThis does not happen to bother my refined aesthetics, but it does present a danger to our lives.\n\nIn the lands of the Lich King, the dead are a weapon that can rise against us at any point in time.  Take this torch - you're going to make sure that doesn't happen.", sourceObjective = "High Executor Anselm at Vengeance Landing wants you to take the Burning Torch and use it to burn 10 of the corpses littered to the west of town.", progress = "I don't care how many giants, dragons or kobolds you've killed before.  Get this job done and come back when you're finished.", completion = "I'm glad you've proven you can follow orders.  If I had a copper piece for every arrogant fool in shiny armor to come here and think they're above the chain of command... well, I'd have a few gold.\n\nNow that you've demonstrated a measure of discipline, I have other tasks more suitable for someone of your caliber.", sourceObjectiveStatus = "unverified-source-field" }
quests[11271] = { id = 11271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hasty Preparations", description = "The down of the spotted hippogryph is prized by my people and used for everything from fletching to ceremonial clothing. We're making preparations to leave the post, so this is the last chance I'll get to gather it this season.\n\nWith your help, I'll have enough to make sure everyone has the equipment they need for the long trek into the hills. Conditions worsen very quickly up there and a storm can blow in without warning.\n\nThe down can be found all over the ground in the area surrounding the post.", sourceObjective = "Ahota Whitefrost at Camp Winterhoof wants you to bring him 10 clumps of Spotted Hippogryph Down.", progress = "Have you gathered any of the down?", completion = "With your contribution, we'll be well prepared for the journey. I haven't much to offer you for your help, but I will give you a choice of some of my spare combat gear.", sourceObjectiveStatus = "unverified-source-field" }
quests[11272] = { id = 11272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Score to Settle", description = "This elf prince thinks he can come to my town, insult my queen, kill my men and get away with it? He thinks we're going to stand by while the hordes of Utgarde build up to launch an attack?\n\nNot in a million years.\n\nYou're going to walk right into Utgarde and kill him. I want Arthas to know that we've arrived and we're playing for keeps.\n\nReport to Dark Ranger Marrah inside Utgarde Keep when the deed is done and she'll tie up any... loose ends.", sourceObjective = "High Executor Anselm wants you to slay Prince Keleseth inside Utgarde Keep.", progress = "Do you have something to report, {class}?", completion = "Revenge feels good.  To think that this is but a taste of what's to come.\n\nArthas will get what he deserves soon enough.  Then and only then will I die a happy man.", sourceObjectiveStatus = "unverified-source-field" }
quests[11273] = { id = 11273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Human League", description = "We were on the brink of an archaeological breakthrough when those monsters attacked! Sadly, I was the only one to make it back to Valgarde. Now I don't know if my crew is dead or alive, but the artifacts we uncovered on that dig must be found!\n\nIf you're heading into Wyrmskull Village, will you keep an eye out for my team? If there's any hope of recovering that information, we must pursue it!\n\nSearch for Pulroy first. He was the last one I saw before I made my escape.", sourceObjective = "Search Wyrmskull Village for Pulroy.", completion = "You've found Pulroy. A bit too late it seems.\n\nWhile looking over the corpse you see a journal clenched tightly in Pulroy's death grip. Upon examining the journal you read what appears to be the scribbling of a dying dwarf.", sourceObjectiveStatus = "unverified-source-field" }
quests[11274] = { id = 11274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zedd's Probably Dead", description = "To whomever finds this journal:\n\nThese bloodthirsty monsters have taken up residence in the ruins of Wyrmskull. What they want or why they're here is a mystery. In any case, the artifacts are not safe with those beast-men around.\n\nZedd and I made a new discovery while hiding out: a cipher to decode the tablets! Unfortunately Zedd and I were separated late last night. He had the cipher. Tablets were with Glorenfeld and Daegarn. Location unknown...\n\nFind Zedd.\n\n-Pulroy", sourceObjective = "Search Wyrmskull Village for Zedd.", completion = "You've found Zedd. You're no doctor but the prognosis for Zedd is most assuredly negative.\n\nIt looks as if they were preparing to feed him to the worgs. Gruesome...", sourceObjectiveStatus = "unverified-source-field" }
quests[11275] = { id = 11275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Horn", description = "My people have been hunting the giant yeti of these hills for generations and I will be participating for the first time this year. It will probably be the last before we leave the post forever.\n\nTo prepare for the hunt, I must fashion a loud horn from the horns of the dire rams that roam the snowy areas near our camp. The elders tell me the sound mimics the mating call of the female yeti, but I have my doubts.\n\nBring me the best dire ram horns you can find, {name}, and I'll select one from among them.", sourceObjective = "Nokoma Snowseer at Camp Winterhoof wants you to bring her 6 Undamaged Ram Horns.", progress = "Have you brought any suitable horns?", completion = "These are all fine horns, {name}. Let me examine them and select the one I will use in the hunt.\n\nI'll give the rest to the craftsmen for use in their carvings.", sourceObjectiveStatus = "unverified-source-field" }
quests[11276] = { id = 11276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Then There Were Two...", description = "There's no sign of the cipher on Zedd. After carefully searching the area you discover some writing in the dirt:\n\n\"Glor and Dae inside catacombs. Have cipher and tablets.\"\n\nPerhaps you should head into the catacombs located just north of here and search for Glorenfeld and Daegarn. The bridge crossing the worg pit will lead you right to the tunnel leading down into the catacombs.", sourceObjective = "Search the Utgarde Catacombs for Glorenfeld.", completion = "About bloody time! Pulroy and Zedd are dead.\n\nAnd Daegarn...\n\n<Glorenfeld shakes his head.>\n\nTaken by the Dragonflayer chieftain into the depths of these catacombs. I overheard that oversized mongrel mention something 'bout a sacrifice to the \"Dread King.\"\n\nThe cipher is hidden away in Daegarn's grimy beard.\n\nWhat? Dwarves hide things in their beards all the time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11277] = { id = 11277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Depths of Depravity", description = "They're keepin' Daegarn locked up in a cage at the large fightin' ring nearby. From what I've gathered, the Dragonflayers bring out their prisoners to battle against their most powerful gladiators. They dump the losers in the basement where Scourge necromancers turn 'em into ghoulies! It's horrifying!\n\nBut first things first! The tablets are strewn about all across this dungeon. Let's get those recovered before you go off tryin' to be a hero.", sourceObjective = "Glorenfeld at the Utgarde Catacombs wants you to collect 10 Wyrmskull Tablets.", progress = "Check every nook and cranny!", completion = "You've done well, mate. Now that we've secured the tablets we can try and save Daegarn's life and recover the cipher that will help us decode the meaning behind these ancient relics!\n\nI'll hold on to these tablets, you rescue Daegarn.", sourceObjectiveStatus = "unverified-source-field" }
quests[11278] = { id = 11278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Valgarde", description = "'Tis a shame we lost two of our best dwarves while uncovering these relics. They sacrificed their lives to keep this information safe.\n\n<Glorenfeld wraps the cipher and tablets in a tattered cloth.>\n\nTake these back to Valgarde. McSorf will know what to do with the find.\n\nAs for me? I'll be alright on my own. I've gotten this far in one piece!", sourceObjective = "Take Glorenfeld's Package to Beltrand McSorf at Valgarde Port.", progress = "You're back!", completion = "Sorting these tablets out is going to take some time. All I can gather from a precursory study is that whatever used to be here was an ancestor of the humans. Those vrykul things probably killed 'em all off. Anyhow, we'll know more once I get these relics set up.", sourceObjectiveStatus = "unverified-source-field" }
quests[11279] = { id = 11279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Eggs and Whelps", description = "This new plague that we're working on is wonderful and I think we should expand its testing.\n\nHow about testing it on proto-whelps?!\n\nJust think of the possibilities. The ability to infect not only humanoids, but extend our reach to any creature!\n\nHere, I've hoarded an extra plague canister for the right time and place, and you look like the right person.\n\nSpray the eggs at Ember Clutch to the northwest, then get specimens from the plagued proto-whelps that hatch.", sourceObjective = "Plaguebringer Tillinghast has asked you to collect 10 Plagued Proto-Whelp Specimens and deliver them to him at New Agamand.", progress = "Without those samples, how am I to tell if this latest strain of the plague can be expanded for use on all sorts of creatures?", completion = "What?! No, this can't be right.\n\nCURSES!\n\nThis batch of the plague doesn't seem to have had any real effect on the proto-whelps at all other than to make them glow green!\n\nMy dream of using the plague upon anything we come into contact with seems to have gone up in smoke!", sourceObjectiveStatus = "unverified-source-field" }
quests[11280] = { id = 11280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconis Gastritis", description = "Wait, that gives me an idea! What if it didn't kill the whelps because it was sprayed on the outside of their eggs?\n\n{name}, we have to get the plague inside of them!\n\nI know! I've got some plagued meat here. Take it to the Ember Clutch and get them to eat it!\n\nBut no, we're thinking too small. Let's get one of the proto-drakes flying overhead to come down and eat it.\n\nYes!\n\nStay close to the meat and observe what happens. Yes, it might attack you, but such is the price of progress.", sourceObjective = "Plaguebringer Tillinghast at New Agamand wants you to use Tillinghast's Plagued Meat to attract down a Proto-Drake and observe its reaction to eating the stuff.", completion = "NOOOOOOOOOOOOOOOO!!!\n\n<The plaguebringer begins to cry.>\n\nAll of my hopes... all of my dreams, ruined!\n\nLeave me, {name}. Leave me to my despair. I'm nothing.\n\nHere, you might as well take all of my worldly possessions. When the rest of the apothecaries hear of my failure, I'll be done for and won't need them anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[11281] = { id = 11281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mimicking Nature's Call", description = "The horn has been roughed out, but before I make the traditional carvings, I want to be certain that it will work. Ahota tells me that he tests his horns at the foot of the frozen waterfall to the northeast of the post. Ahota tells me that our hunters have used the acoustics of frozen water in this way for generations. I can't wait to learn more!\n\nWill you help me test out the horn? If I've done everything right, you may even attract a yeti, so be prepared! Bring the horn back once you've tested it.", sourceObjective = "Test the Carved Horn and then return to Nokoma Snowseer at Camp Winterhoof with the results.", completion = "<Nokoma listens to your report from the test.>\n\nI'm relieved that the horn worked so well... maybe too well if what you're saying was true. You're sure the beast spoke? I don't know if I can go on with the hunt if that's true. I'll have to speak with Chief Ashtotem about it.\n\nThis horn may end up being merely decorative, but that won't diminish its worth. Thank you for all your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11282] = { id = 11282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Fear", description = "When you've been in lots of fight like Gorth, you learn that to beat enemy good you have to make them really scared to die!\n\nBut these vrykuls not afraid.  You kill one and another comes... screaming louder and with a bigger weapon than the one before.\n\nOnly thing that makes vrykuls afraid is when we kill the biggest and baddest vrykul of all.\n\nGo fight the Winterskorn across the blockade until hero vrykuls show up!  Then you kill them dead and put queen's flag on corpses.  They must learn to fear!", sourceObjective = "Gorth wants you to kill Ulf the Bloodletter, Oric the Baleful and Gunnar Thorvardsson and drive the Forsaken Banner through their corpses. Slay Vrykul across the Forsaken blockade until they appear.", progress = "You kill them vrykuls?  They sure is tough!", completion = "You do some good killings over there.  I see vrykul men fall and get stabbed with Sylvanas flag.  Our side doing good!", sourceObjectiveStatus = "unverified-source-field" }
quests[11283] = { id = 11283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baleheim Bodycount", description = "Them vrykuls just keeps coming and coming out from town west of here.  No end in sight!\n\nGorth has an idea.  You go INSIDE town and kill them Winterskorn there.  THEN they stop coming here!", sourceObjective = "Sergeant Gorth wants you to kill 16 Winterskorn Vrykul inside Baleheim.", progress = "You done with the killings yet?  Winterskorn town right across from here!", completion = "You must have lots of practice with doing killings.  You almost as good as Gorth!", sourceObjectiveStatus = "unverified-source-field" }
quests[11284] = { id = 11284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Yeti Next Door", description = "Maybe if the sentries won't help me, you will? I'm the foreman of the mine just across the bridge. My men are mining ore for the weapons our expeditionary force will need to carve a path into the Grizzly Hills.\n\nA giant yeti has invaded the mine, blocking the tunnel we need to expand! We've tried yelling at him and smoking him out, but nothing's worked.\n\nMaybe you could rouse it from its sleep with a meal of meat from the frosthorn rams in the snowy areas around town? Please? We're desperate!", sourceObjective = "Foreman Colbey at Fort Wildervar wants you to defeat Shatterhorn.", progress = "Have you had any luck removing that stupid yeti from my mine?", completion = "You've done it? By the Light, you're a walking miracle! I was beginning to think I'd personally have to explain to Captain Adams why his men's weapons weren't ready in time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11285] = { id = 11285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baleheim Must Burn!", description = "Killing the Winterskorns maybe not enough.  Maybe we burn their houses too!  Uh... and their bridges.  We should burn whole town to be safe!\n\nYou take this torch.  Go to Baleheim, to the west, and burn EVERYTHING!  That teach them good.", sourceObjective = "Sergeant Gorth wants you to go to Baleheim and use Gorth's Torch to burn 1 Winterskorn Dwelling, 1 Winterskorn Watchtower, 1 Winterskorn Bridge and 1 Winterskorn Barracks.", progress = "You done burning everything?  Make sure you not leave something not burned.", completion = "I guess you burned everything.  I see couple of spots not burning... but is close enough for Gorth.", sourceObjectiveStatus = "unverified-source-field" }
quests[11286] = { id = 11286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Artifacts of Steel Gate", description = "I came out here for a different reason; an old friend of mine has been calling to me in my dreams. But now that I see these small things with their machines making a big hole in the ground, it makes my blood boil.\n\nFrom what I can see, these dwarves, as they are known, are digging up artifacts; artifacts that could be important to our past.\n\nI want you to go down there and get these things for me. Don't let any of those dwarves stand in your way.", sourceObjective = "Sage Mistwalker has asked you to collect 10 Steel Gate Artifacts. When you have all of them, return to him at Steel Gate.", progress = "How many artifacts have you managed to gather from this Steel Gate?", completion = "<The sage grunts his approval at your actions on his behalf.>\n\nPerhaps I will be able to find the time soon to study these artifacts and come to an understanding of their significance.\n\nBut now there are more pressing matters to attend to.", sourceObjectiveStatus = "unverified-source-field" }
quests[11287] = { id = 11287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Sage Mistwalker", description = "{class}, I grow worried that my son, Sage Mistwalker, has been gone for such a long time. The land is cruel and deadly.\n\nHe spoke of a recurring vision that he had of a wolf, and went west with a small group of longrunners to seek its source. I believe the name of the place he mentioned was Steel Gate.\n\nWill you find him? I want to make sure that no ill has befallen him.", sourceObjective = "Greatmother Ankha has asked you to check on the condition of Sage Mistwalker. She believes him to be at or near Steel Gate.", completion = "My mother should not concern herself with my safety. But, I thank you for coming, stranger.\n\nSince you are here, perhaps you will help me with a few things?", sourceObjectiveStatus = "unverified-source-field" }
quests[11288] = { id = 11288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shining Light", description = "<Ares gasps for air as he tries to speak.>\n\nI am an envoy of the Argent Crusade, charged with a sacred duty.\n\nOur forces were decimated in the Plaguelands. By the light of dawn, the artifact was cleansed and made pure once more. So many perished in the wake of its redemption.\n\nThere is still a chance... still time.\n\nThe artifact was hurled into the den of the fallen, far below us. Guarded by the unmerciful dead.\n\n<Ares' body glows with blinding light.>\n\nLight. Will. Protect. You.", sourceObjective = "Ares the Oathbound in the Utgarde Catacombs wants you to recover the Sacred Artifact.\n\nThis is a timed quest.", progress = "<Ares is unconscious.>", completion = "You feel compelled to place the sacred blade next to the body of Ares.\n\nUpon doing this you are once again blinded by light.", sourceObjectiveStatus = "unverified-source-field" }
quests[11289] = { id = 11289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guided by Honor", description = "<Ares smiles.>\n\nGlory to the Light. You have done it!\n\n<Ares coughs.>\n\nTake the artifact and return it to Valgarde. Lord Irulon Trueblade awaits its return.\n\nFight with honor, friend. Always. Honor.\n\n<Ares dies.>", sourceObjective = "Return the Sacred Artifact to Lord Irulon Trueblade at Valgarde.", progress = "By the Light!", completion = "Many men and women died to recover this blade. Alas, I fear valiant Ares will not be the last.\n\nBut you do the Light's work, hero. This sacred blade will be wielded by Lord Tirion Fordring himself. Even now the Argent Crusade works toward Icecrown. Lord Fordring has vowed that he will tear down the walls of the cursed place himself! And with the blade, he just might stand a chance against the Lich King.\n\nLord Fordring remains our greatest hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[11290] = { id = 11290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflayer Battle Plans", description = "While we were able to gather very little information as to the whereabouts of Ingvar, we do know that Yanis resides in a cave next to the worg pit inside Wyrmskull Village.\n\nIntelligence gathered from the rescued soldiers indicates that Yanis guards Dragonflayer battle plans.\n\nI need you to go back to Wyrmskull and recover those plans. Kill any vrykul that get in your way - including Yanis!", sourceObjective = "Vice Admiral Keller at Valgarde Port in the Howling Fjord has asked that you bring him the Dragonflayer Battle Plans.", progress = "Have you recovered the Dragonflayer battle plans?", completion = "<Vice Admiral Keller glances over the plans.>\n\nOutstanding! By the looks of things, there are many more vrykul villages in the fjord. A different tribe of vrykul is preparing an assault on Westguard Keep. Hell, for all I know it may already be too late. We haven't heard from Westguard in days. Either way, we must alert Westguard!", sourceObjectiveStatus = "unverified-source-field" }
quests[11291] = { id = 11291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Westguard Keep!", description = "<Vice Admiral Keller rolls up the battle plans.>\n\nWe've got all the information we need to keep Valgarde protected. You must take these battle plans to Westguard Keep, located on the western fjord cliff wall. Speak with the flight master assistant, Emilune Winterwind. She will put you on the back of a gryphon headed towards Westguard.\n\nOnce there, find Captain Adams. He's the one in charge. Adams will know what to do with these plans.", sourceObjective = "Take the Dragonflayer Battle Plans to Captain Adams at Westguard Keep in the Howling Fjord.", progress = "Valgarde has not fallen? That's a surprise.\n\nMust be due to your help. It sure wasn't because of Keller.", completion = "<Captain Adams takes the plans from you.>\n\nI'm glad you decided to come over. My advisors and I will need some time to study these plans. In the meantime, we can use all the help we can get!", sourceObjectiveStatus = "unverified-source-field" }
quests[11292] = { id = 11292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preying Upon the Weak", description = "Glad to meet you. I've come here from the Grizzly Hills to do business with your cohorts. My people maintain a large outpost there, and you'd do well to visit it when you head north.\n\nI've set up traps in the woodlands and snowy areas around here. With the meat and the furs from the creatures they capture, I'll have plenty to barter with the townspeople.\n\nI can offer you a share of my profits if you're willing to help gather prey from the traps. Beware though, you won't be the only predator out there.", sourceObjective = "Trapper Jethan at Fort Wildervar wants you to bring him 8 pieces of Trapped Prey.", progress = "I hope you haven't returned empty-handed. I thought we had a deal.", completion = "<Trapper Jethan inspects the creatures you've brought him.>\n\nNicely done. Some of these will fetch a better price than others, but I should have plenty to trade with the locals.", sourceObjectiveStatus = "unverified-source-field" }
quests[11293] = { id = 11293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for the Barleybrews!", description = "We need to get the word out about the Barleybrews at Brewfest.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.  I'll make things easy though, I'll lend you a racing ram for 4 minutes.  Use the reins to let him go, but try not to tire him out.", sourceObjective = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the Barleybrews?", completion = "Well done!  That kinda shouting is sure to bring business our way.\n\nAnd we promised you a reward, here it is.  The Barleybrews keep their word.\n\nOh, and come back any other day if you want to help spread the good name of Barleybrew.", sourceObjectiveStatus = "unverified-source-field" }
quests[11294] = { id = 11294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for the Thunderbrews!", description = "It's time to let people know that the Thunderbrew have heard their cries for good brew.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.\n\nWe'll make it easy though.  We'll lend you a ram for 4 minutes.\n\nBe careful with going too fast though since you won't find any apple crates in Ironforge...  We can't take the chance of helping out the Barleybrew messengers.", sourceObjective = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", progress = "Did you let everyone know that the Thunderbrews are here at Brewfest?", completion = "Good job!  That'll show those arrogant Barleybrews.\n\nWell we promised you a reward and here it is.  We Thunderbrew reward you with prizes, the Barleybrew reward you with foul odors and false promises.\n\nYou chose wisely.\n\nIf you want to keep making the right choice, stop by another day and help us spread the word.", sourceObjectiveStatus = "unverified-source-field" }
quests[11295] = { id = 11295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Offensive Begins", description = "No one seems to know very much about the vrykul.  Our records show no signs of activity in their lands for centuries.  Yet here they are, just as we move against Arthas.\n\nThe map you retrieved makes it clear that we'll have to defeat them if our forces are to get any further into Northrend.\n\nOne of my best sergeants, an abomination known as Gorth, oversees the blockade beyond the lift.  Assist him in launching a pre-emptive strike on Baleheim.  If a vrykul attack occurs, it will be launched from there.", sourceObjective = "Speak to Sergeant Gorth at the blockade near the elevator west of Vengeance Landing in Howling Fjord.", completion = "You come to help?  Good... good...\n\nGorth was getting tired of killing vrykuls all day.  Help is welcome!", sourceObjectiveStatus = "unverified-source-field" }
quests[11296] = { id = 11296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rivenwood Captives", description = "Something, most likely the walking dead known as the Scourge, has agitated the creatures hereabouts.\n\nWhile escorting the sage here, we lost most of our hunting force to the riven widows -- huge and deadly spiders, which inhabit the Rivenwood to the north.\n\nI must stay here to protect the small force we have left, but you... you could see if my longrunners are still alive, trapped within the riven widow's cocoons.\n\nWould you do this, stranger?", sourceObjective = "Longrunner Skycloud has asked you to free his 7 Winterhoof Longrunners. Once you have managed to do so, return to him at Steel Gate.", progress = "I hold out hope that my hunting force is still alive.\n\nThe sting of the widows is slow to be fatal. They like to keep their victims alive long enough that their babies will be able to gorge themselves when they hatch.", completion = "That was a very brave act, {class}. I did not know that your people were capable of such selflessness.\n\nNext time I will heed the warnings of my elders and steer clear of the Rivenwood. I advise you to do the same.", sourceObjectiveStatus = "unverified-source-field" }
quests[11297] = { id = 11297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping Watch on the Interlopers", description = "Even the earth cannot hold back the tide of death washing over it. Corpses walk the land, spreading their putrefaction with alarming speed.\n\nA small expedition has made its way up the western cliffs and rests near Whisper Gulch. Take a look for yourself, {name}. See if you can learn their purpose and dissuade them from bringing their poisons into our lands. Travel southwest from the post, toward the cliffs overlooking the western beach. Their camp will be west of the excavation at Steel Gate.", sourceObjective = "Speak to Apothecary Malthus at the Apothecary Camp.", completion = "Ah, yes, the reclusive bison-men of the north. I've seen them skulking about, believing themselves unseen. I suppose they fancy this land theirs? Well, that's but one of many things that will change shortly.\n\nI wasn't expecting any company, but while you're here on that fool's errand, you might as well make yourself useful.", sourceObjectiveStatus = "unverified-source-field" }
quests[11298] = { id = 11298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's in That Brew?", description = "To the southeast is an area called Whisper Gulch. It's overrun with members of the Explorers' League who've gone mad! They attacked our caravan as it passed through the area, and they've harried our foraging parties as well.\n\nI must know what's causing this madness! I suspect that whatever they're drinking from the kegs scattered around the gulch contributes to their insanity. I want you to steal the kegs from those dwarves while they're busy mining away.", sourceObjective = "Apothecary Malthus at the Apothecary Camp wants you to bring him 5 Dwarven Kegs.", progress = "Did you get those kegs or not?", completion = "<The apothecary pours out a tankard of the beverage for himself.>\n\nWell, here I go!", sourceObjectiveStatus = "unverified-source-field" }
quests[11299] = { id = 11299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Judgment", description = "You might have already seen the room where Daegarn is being held while you were gatherin' the tablets. It's through this corridor and then down a set of steps. Daegarn will be in the room at the bottom of the steps - locked up tight!\n\nGet down there and find him. At the very least you might be able to get the cipher from him.", sourceObjective = "Find Daegarn in the Ring of Judgement located inside the Utgarde Catacombs.", completion = "Yep. You found me. Woopedy-do!\n\nAnd no, I don't have the cipher. My beard was the first thing those beasts checked! Oluf's the one that's got it now. He's the chieftain of the gladiators.", sourceObjectiveStatus = "unverified-source-field" }
quests[11300] = { id = 11300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stunning Defeat at the Ring", description = "Oluf will come out if you defeat the other gladiators. That's 'bout the only way we're getting' that cipher back. Put on your whompin' boots and get busy in the Ring of Judgement. If you do manage to get the cipher back, return it to Glorenfeld o'er near the entrance to these catacombs.\n\nMe? Don't worry about me! We're on the brink of discovering the missing link to human-kind!", sourceObjective = "Defeat the gladiators at the Ring of Judgement and face Oluf the Violent. Defeat Oluf and recover the Ancient Cipher.\n\nReturn the Ancient Cipher to Glorenfeld at the entrance to the Utgarde Catacombs.", progress = "Daegarn? The cipher?", completion = "Fascinating tale! Something is actually judgin' these things? To what end?! For what purpose?\n\nWell, never mind that nonsense. Someone else can figure out that stuff. We got the cipher and the tablets back - and only two fatalities in the whole ordeal.", sourceObjectiveStatus = "unverified-source-field" }
quests[11301] = { id = 11301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brains! Brains! Brains!", description = "Has Malthus drawn you in with his blather about beer kegs and crazy dwarves?\n\nI'm not questioning that the dwarves are crazy, but I don't think stealing their beer is going to do any good.\n\nWhat we need is brains. Lots of brains. We'll get down to the bottom of this mystery in no time, and perhaps even find a new component for the plague.\n\nTake this saw, go southeast into the Whisper Gulch, and kill yourself some dwarves. Use the saw to help you harvest the brains and bring them back here.", sourceObjective = "Apothecary Grick at the Apothecary Camp wants you to bring him 12 Deranged Explorer Brains.", progress = "Did you get those brains? If not, I want my saw back. You'd better not walk off with that saw.", completion = "These brains are beautiful! Gorgeous, even! They're exactly what I need.\n\nThank you for your help, {name}. Now I'll show Malthus the truth his beer goggles couldn't reveal.", sourceObjectiveStatus = "unverified-source-field" }
quests[11302] = { id = 11302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enigmatic Frost Nymphs", description = "When we first scouted locations for the fort, we encountered hostile creatures at two of the glades here in the north. When we passed the snow-covered one directly south of the town, the dryads there watched us with interest, but did not attack.\n\nWe were tired and worn down by the weather. They could've easily killed several of our men, but they didn't.\n\nPerhaps, in reaching out to them, we might discover unexpected allies. Are you willing to travel to the Frozen Glade and make contact with them?", sourceObjective = "Speak with Lurielle at the Frozen Glade.", completion = "<Lurielle listens as you introduce yourself.>\n\nIt is good to finally meet you, {name}. We have long hoped that you and the other newcomers might send representatives. We don't often venture beyond the borders of our glades, especially amid the changes the land is going through.", sourceObjectiveStatus = "unverified-source-field" }
quests[11303] = { id = 11303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ambush", description = "The vrykuls in Baleheim is completely defeated, no doubt about it.  But still their leader stays in town and won't give up.\n\nGorth sends Lydell and his assassins to make good ambush to the northwest.  You talk to Lydell and figure out how to get Vrykul chieftain to come out.  Then you kill him.  You kill him real good.", sourceObjective = "Speak to Lydell at Lydell's Ambush.", completion = "We all showed up to the party, but the guest of honor stayed at home.", sourceObjectiveStatus = "unverified-source-field" }
quests[11304] = { id = 11304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Agamand", description = "I'm afraid our equipment isn't exactly the best here at Vengeance Landing.  After all it's a military controlled outpost.\n\nI will need you to take a sample of this strain to Chief Plaguebringer Harris in New Agamand, follow the road beyond Baleheim south and then west.  They have better equipment there - he will know what to do.\n\nYou must hurry, {name}.  Our enemies are stronger and more numerous than us.  We need to develop a viable weapon against them!", sourceObjective = "Bring Lysander's Strain to Chief Plaguebringer Harris in New Agamand in western Howling Fjord.", progress = "Yes, {name}?", completion = "This strain is far from worthless, my friend!  Those fools at Vengeance Landing have had all the answers right under their own noses!", sourceObjectiveStatus = "unverified-source-field" }
quests[11305] = { id = 11305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tailor-Made Formula", description = "We've been spraying down the vrykul village of Halgrind for weeks now and the vrykul just won't drop dead.\n\nLet's face it, {name}, by now our Plague has been exposed to humans, dwarves, dogs, livestock... you name it.  As our strains adapt to their hosts, more impurities get thrown in the mix.  What we need is a strain made custom for the vrykul's biology.\n\nHalgrind's chieftain fled the town after we took it over; you'll find him west of here.  As a patriarch of the Dragonflayer clan, his blood is ideal.", sourceObjective = "Obtain the Dragonflayer Patriarch's Blood from Thorvald at Thorvald's Camp and bring it to Chief Plaguebringer Harris in New Agamand.", progress = "Have you obtained the sample I require, {name}?", completion = "This will do.  It's time for some real apothecary work now, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11306] = { id = 11306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apply Heat and Stir", description = "You've done well so far, {name}.  I'd like to teach you some of my more advanced techniques, so that you gain a better understanding of the plague.\n\nTake this empty flask and fill it with blood from the cauldron to my left.  Mix it with the plague samples to my right until you obtain a well balanced mix.", sourceObjective = "Fill the Empty Apothecary's Flask at the Cauldron of Vrykul Blood, then mix the Flask of Vrykul Blood with Harris's Plague Samples nearby until you've obtained a Balanced Concoction.\n\nReturn to Chief Plaguebringer Harris when you've completed this task.", progress = "How is your experiment going, {name}?  Let me know if you have any questions behind the science involved!", completion = "Excellent!  You are an apt pupil, {name}.\n\nNow comes the fun part.  Deployment!", sourceObjectiveStatus = "unverified-source-field" }
quests[11307] = { id = 11307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Test", description = "Now that we have a strain of the plague that has adapted to vrykul carriers, we really ought to test it on our specimens in Halgrind.  If all goes according to plan, they will disintegrate immediately as the plague devours their innards!\n\nYou will find Halgrind north of here.  Our plaguebringers are deploying the previous strain there - shouldn't be hard to spot.", sourceObjective = "Venture into Halgrind and use the Plague Spray on 10 Plagued Dragonflayer Vrykul. Return to Chief Plaguebringer Harris to report the results.", progress = "Have you completed your field tests, {name}?", completion = "The plague didn't disintegrate our subjects?  Are you certain, {name}??!\n\nThere must be an external factor we're not accounting for... perhaps the low temperatures of this climate?  Perhaps... a mutation in the strain!", sourceObjectiveStatus = "unverified-source-field" }
quests[11308] = { id = 11308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Cleanup", description = "Being the practical man that I am, I'm going to declare our research here a success.  After all, what army can't be stopped by turning its rank and file against each other?\n\nI will send word of our achievements to Vengeance Landing soon enough.  But first I need you to take care of cleaning up our experimentation site.\n\nSee \"Hacksaw\" Jenny about making you a custom abomination.  One packing some explosive power if you catch my drift.", sourceObjective = "Speak to \"Hacksaw\" Jenny in New Agamand.", completion = "What do you want?  Can't you see I'm in the middle of something?", sourceObjectiveStatus = "unverified-source-field" }
quests[11309] = { id = 11309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts for the Job", description = "So Harris wants a demolition job, eh?  Yeah, I can help out.\n\nYou're gonna have to get me some parts, though.  I can't afford to use up my choice components on something that's gonna get blown up.\n\nFirst of all, I'm going to need shoveltusk ligaments... way better than the human kind.\n\nI will also need a pound of flesh.  A fellow known as Anton sells cheap meat.  He travels up and down the road to the west.", sourceObjective = "\"Hacksaw\" Jenny in New Agamand wants you to obtain 6 Shoveltusk Ligaments and 1 Fresh Pound of Flesh.", progress = "You get my components yet?", completion = "Excellent!  Yes, yes, these will do just fine!", sourceObjectiveStatus = "unverified-source-field" }
quests[11310] = { id = 11310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning: Some Assembly Required", description = "Well, here you are!  Our friend's going to be somewhat... unstable.  So I suggest not putting him together until reaching Halgrind.\n\nOnce you're there, use the abomination to round up as many vrykul as you can before self-destructing.\n\nCome back with whatever's left once you're done.  I can always use more body parts!", sourceObjective = "Use the Abomination Assembly Kit in Halgrind and round up plagued Vrykul with your Mindless Abomination. Slay at least 20 and return to \"Hacksaw\" Jenny in New Agamand when you're done.", completion = "Great job, {name}.  Say, you wouldn't be looking for something more... permanent, would ya?  I could sure use some help around these parts!", sourceObjectiveStatus = "unverified-source-field" }
quests[11311] = { id = 11311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suppressing the Elements", description = "If you are to survive here, as we have, you must learn to face the environment's challenges head on. The elements will claim your life if you're not vigilant, as the proliferation of elementals in these northern hills shows.\n\nWe must cull the elementals one last time before we can leave this place. Are you willing to aid us while we continue to make preparations?\n\nYou must kill any iceshard elementals or howling cyclones you encounter in the snowy hills surrounding the outpost.", sourceObjective = "Wind Tamer Kagan at Camp Winterhoof wants you to kill 8 mountain elementals. You may kill either Howling Cyclones or Iceshard Elementals.", completion = "The influence of the elemental spirits has receded, but it will return. We've bought ourselves the time we need to complete our tasks here and take our leave.", sourceObjectiveStatus = "unverified-source-field" }
quests[11312] = { id = 11312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frozen Glade", description = "For generations, my people have told tales of frost nymphs cavorting in glades hidden away in the wilderness. I used to search for them as a child, against the advice of my parents, until I nearly froze to death.\n\nThese days, it isn't necessary to comb the forests for them. They've decided to reveal themselves for reasons I can only guess, but I don't think the change can be ignored. Venture southeast to the Frozen Glade and seek out the nymphs, but beware; you will pass the Twisted Glade on your way.", sourceObjective = "Speak with Lurielle at the Frozen Glade.", completion = "<Lurielle listens as you introduce yourself.>\n\nIt is good to meet you, {class}. My sisters have often watched the taunka search the forests for us, but we are forbidden by our queen from interacting with outsiders. You only see us now because the land has become unsettled and many of my sisters are in danger.", sourceObjectiveStatus = "unverified-source-field" }
quests[11313] = { id = 11313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Ice", description = "The ice elementals surrounding our glade were once our companions, but a volatile and destructive force has swept through the land, turning them against us!\n\nThis is but one of the horrors my sisters and I have endured. We have revealed ourselves to you in the hope that you will help us stave off the decay that has crept into our glades and poisoned our sisters!\n\nWe've been gathering the cores of the ice elementals and keeping them safe so that one day, we might be able to restore them. Will you help?", sourceObjective = "Lurielle at the Frozen Glade wants you to bring her 15 Icy Cores.", progress = "Have you recovered any of the cores?", completion = "<Lurielle accepts the cores from you quietly.>\n\nThank you, {name}.\n\n\n\nI promise, my friends, I will do all I can to restore you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11314] = { id = 11314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Sisters", description = "To the southwest was a glade that used to look much like this one. Mysterious forces and alien magics are reshaping the land. The glade has thawed, the sisters living there driven mad by the sudden change.\n\nWe thought to reach out to them, but they attacked us. I fear many may be beyond saving, but I cannot give up hope.\n\nTake my pendant, travel southwest to the Vibrant Glade, and use it to try to free my sisters.", sourceObjective = "Lurielle at the Frozen Glade wants you to use her pendant on 7 Chill Nymphs.", progress = "Were you able to heal any of my sisters using the pendant?", completion = "So there is hope for my sisters?\n\n<Lurielle looks away from you, then down at the ground.>\n\nI feel guilty for not thinking of the pendant sooner. We might have saved even more of the sisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[11315] = { id = 11315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Vines", description = "The sisters who lived in the Vibrant Glade, to the southwest, used to tend to gorgeous beds of scarlet ivy, but the same force that has driven them mad has transformed their beloved ivy.\n\nThe vines now grasp at the feet of the unwary, or lash at any who approach the glade. Before we can reclaim the glade, the vines must be tamed and uprooted.\n\nClear as much of the ivy as you are able. It has already begun to grow out of control.", sourceObjective = "Lurielle at the Frozen Glade wants you to kill 8 Scarlet Ivy.", completion = "Thank you for your help, {name}. The Vibrant Glade was once a beautiful place, and when we return to it, we shall make it so again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11316] = { id = 11316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spawn of the Twisted Glade", description = "The glade to the west has been transformed into a hideous place called the Twisted Glade. Horrible beasts dwell among the trees, stones, and pool of the glade.\n\nI cannot guess where the creatures came from or what horrible forces animate them, but they must be dealt with!\n\nI fear that if they are allowed to dominate the glade, they will poison it beyond redemption. Clear the glade of these creatures who murdered our sisters.", sourceObjective = "Lurielle at the Frozen Glade wants you to kill 10 Thornvine Creepers.", progress = "Have you seen the horrors of the Twisted Glade for yourself?", completion = "You have done well, {name}. If we'd had allies like you when the land first began to change, perhaps we might have been able to preserve some of what we've lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[11317] = { id = 11317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleansing", description = "We braved the Rivenwood because of my troubled dreams concerning my worg life-friend, Ulfang. He has called out for help, and you must go to him.\n\nBut, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.\n\nFirst, you must cleanse your inner turmoil.\n\nThere is a shrine that sits at the top of Frostblade Peak, northeast of Camp Winterhoof. A single path leads up to it from the western base of the mountain.\n\nMeditate there and then return to me.", sourceObjective = "Sage Mistwalker at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.", progress = "Did you find inner peace at the shrine? Is your turmoil gone?", completion = "Already I can sense the change within you.\n\nAre you ready for what comes next?", sourceObjectiveStatus = "unverified-source-field" }
quests[11318] = { id = 11318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams?  Well I hope you're ready for speed.  BUT before I let you loose in the world, you'll need to show me that you can handle these fine creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.  If you need instructions how to handle the ram, talk to my apprentice, Pol Amberstill.", sourceObjective = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", progress = "Were you able to handle the speed?", completion = "Nice work there!  It takes time to get the hang of controlling your ram.  But once you do, you'll wish every ram was a racing ram.\n\nWhat's that? \"Where's my reward?\"  Ha Ha Ha... you got to ride the fastest ram around!  You want more?  Well how about this...\n\nYou've been rewarded with the chance to help other people around Brewfest.  There's plenty of work, and rewards, for an eager, young, ram racer.", sourceObjectiveStatus = "unverified-source-field" }
quests[11319] = { id = 11319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of the Blacksouled Keepers", description = "The glade to the northwest, now the Twisted Glade, used to be home to a number of keepers of the glade. Together with the sisters, they saw to the glade's upkeep.\n\nWhen the glade changed, the sisters died, but somehow the keepers managed to survive. Now, they seed the land with poisonous spores that wither healthy greenery.\n\nI'll give you one of the cores from the ice elementals. Once you've destroyed a spore, use the ice crystal to freeze it and keep it from regenerating.", sourceObjective = "Lurielle at the Frozen Glade wants you to freeze 8 Spores.", progress = "The Twisted Glade is a terrible place. I never imagined our homes could become something so loathesome.", completion = "The ice core worked well for you? I'll have to remember that. I'm certain the keepers will not stop just because we've destroyed their work once.", sourceObjectiveStatus = "unverified-source-field" }
quests[11321] = { id = 11321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Did Someone Say \"Souvenir?\"", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", sourceObjective = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11322] = { id = 11322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleansing", description = "Of late I've had nightmares concerning a worg named Ulfang. He has called out for help, and you must go to him.\n\nHowever, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.\n\nBut first, you must cleanse your inner turmoil through meditation.\n\nThere is a shrine that sits at the top of Frostblade Peak, far to the northeast. A single path leads up to it from the western base of the mountain.\n\nMeditate there to cleanse yourself and then return to me.", sourceObjective = "Watcher Moonleaf at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.", progress = "Did you find inner peace at the shrine? Is your turmoil gone?", completion = "Already I can sense the change within you.\n\nAre you ready for what comes next?", sourceObjectiveStatus = "unverified-source-field" }
quests[11323] = { id = 11323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Worg's Clothing", description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.\n\nHe is in great danger.\n\nI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.\n\nPlease, {class}, find and help him.", sourceObjective = "Sage Mistwalker has asked you to seek out and help Ulfang in the Rivenwood.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.\n\nProvided item:", completion = "You look and smell different... you are not one of my pack. Tell me your story; I have nothing but time while I am trapped in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11324] = { id = 11324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Worg", description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat!\n\n{race}-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Mistwalker that I am once more the alpha worg!", sourceObjective = "Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Sage Mistwalker at Steel Gate.", progress = "{name}, you have returned. What news of Ulfang?", completion = "Garwal was not a worg at all! I know of these creatures... they are called worgen.\n\nBut, Ulfang indicated that it came south from the Grizzly Hills? Odd. There aren't any worgen there.\n\nI thank you for helping to restore Ulfang to his proper place amongst his pack. Now we both will be able to sleep peacefully.\n\nPlease, you must accept this as a sign of gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[11325] = { id = 11325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Worg's Clothing", description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.\n\nHe is in great danger!\n\nI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.\n\nPlease, {class}, find and help him.", sourceObjective = "Watcher Moonleaf has asked you to seek out and help Ulfang in the Rivenwood.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.\n\nProvided item:", completion = "You look and smell different... you are not one of my pack. Tell me your story; I have nothing but time while I am trapped in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11326] = { id = 11326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Worg", description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat!\n\n{race}-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Moonleaf that I am once more the alpha worg!", sourceObjective = "Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Watcher Moonleaf at Steel Gate.", progress = "{name}, you have returned. What news of Ulfang?", completion = "Garwal was not a worg at all! The thing you describe him turning into sounds a lot like a worgen!\n\nBut, Ulfang said that it came south from the Grizzly Hills? Odd. There aren't any worgen there.\n\nI thank you for helping to restore Ulfang to his proper place amongst his pack. Now we both will be able to sleep peacefully.\n\nPlease, you must accept this as a sign of gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[11327] = { id = 11327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Package Retrieval", description = "Well darn, we need some of that plague-stuff.\n\nI know!\n\nWhile you were destroying the vats, I happened to spy one of the apothecaries from New Agamand being pulled into Halgrind by the vrykul down in there. Poor fella'.\n\n{name}, I'd bet anything that apothecary has the goods on him. Think you could go into Halgrind and retrieve his package?", sourceObjective = "Scout Knowles has asked you to retrieve the Apothecary's Package from inside Halgrind. Once you have it, return to the scout at the Ember Spear Tower.", progress = "That place looks like a nightmare. Vrykul or not, no one deserves to be the victim of the Royal Apothecary Society.\n\nGlad I'm standing safely over here. You find that package yet?", completion = "Holy... what the hell?! Look at this stuff!\n\nWe need to get this back to the keep a.s.a.p.!", sourceObjectiveStatus = "unverified-source-field" }
quests[11328] = { id = 11328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Forsaken Intel", description = "Right, so I think you should get this stuff over to Peppy Wrongnozzle back at the keep. She's something of an amateur alchemist, but she's the only one we've got.\n\nOne thing about Peppy; she does love her drink. So, you'll likely find her at the tavern 'soaking up the atmosphere'.\n\nI'm sure she'll know what to do.", sourceObjective = "Scout Knowles has asked you to deliver the Apothecary's Package to Peppy Wrongnozzle at Westguard Keep.", progress = "Yeah, whadya want ...hic?", completion = "Oh... hey, that'sh different!\n\nOkay, let me shee that shtuff. I jusht love tinkering with alchemy!\n\nInteresting, interesting... here, I think I know jusht what to do. A little mixing of that with the jusht the right amount of thish.\n\nYou know, I think a little dash of this rotgut will help, too ...hic!", sourceObjectiveStatus = "unverified-source-field" }
quests[11329] = { id = 11329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Try Anything!", description = "I never want to see another barrel of salted fish as long as I live! Filling barrels day in and day out, and there are still more to be filled!\n\nI wish I hadn't used up all that bait I bought from Nat Pagle. Worked like magic, it did. Now I'm lucky if I can catch a fish an hour!\n\nI hear the northern barbfish make pretty good bait, but who's crazy enough to dive into a freezing cold lake and hack up the water plants in search of them? Not me... but maybe, just maybe, I can persuade you to...", sourceObjective = "Christopher Sloan at Fort Wildervar wants you to bring him 5 Northern Barbfish.", progress = "You look like you're still in one piece. Get any of that bait?", completion = "Well, these certainly are ugly enough, but I suppose I don't care if it actually works. I'll be relieved once the expedition has passed through and I can go back to simply fishing for my dinner.", sourceObjectiveStatus = "unverified-source-field" }
quests[11330] = { id = 11330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absholutely... Thish Will Work!", description = "Voila, inshtant plague vacshine!\n\nBut I sure as heck am not going to try thish on myself. And I know you don't want to be my tesht shubject!\n\nOh, I've got... I've got an idea!\n\nWe've got a vrykul prishoner being held down in the cells under the keep. Why don't you take thish mix I whipped up down there, and get that giant to drink it ...hic?!", sourceObjective = "Peppy Wrongnozzle at Westguard Keep has suggested that you take her Peppy's Special Mix and administer it to the Dragonflayer Vrykul Prisoner to witness its results.", completion = "Huh? Well that sucks! Darn, I made thingsh worsh. In fact, I think I perfected their plague for them ...hic!\n\n<Peppy grimaces and takes a huge gulp of whatever noxious brew she's been drinking.>\n\nWell, I wash hoping that it wouldn't come down to thish, but it looks like there'sh no alternative ...hic.", sourceObjectiveStatus = "unverified-source-field" }
quests[11331] = { id = 11331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Tell Him ...Hic!", description = "Here'sh the deal. I'm not going to the captain with thish news. I'm an amateur alchemist, thish ishn't my job, and I'm on break!\n\nBeshides, he'sh a big grumpkin... and you know him better than I do!\n\nSho, jusht go up into the keep and tell him. I'm sure he'll be reashonable about the whole thing ...hic.\n\n<Peppy turns back to her drinking.>", sourceObjective = "Peppy Wrongnozzle has suckered you into giving the bad news about the Forsaken plague to Captain Adams. Visit him at Westguard Keep.", completion = "Yes, {name}, what is it now?\n\nWHAT?!! A Forsaken super plague that melts you in no time?\n\nYou oozed my vrykul prisoner?\n\n\n\nAlright, I know what we need to do. Or rather, what YOU need to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[11332] = { id = 11332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Plague This!", description = "The Royal Apothecary Society thinks they're going to perfect a new plague to melt us down where we stand?!\n\nNot on my watch!\n\nGet out to the courtyard and speak with Greer Orehammer. He's got a gryphon and some bombs ready for you. I want you to bomb the plague tanks at New Agamand to smithereens!", sourceObjective = "Captain Adams has ordered you to get 5 bomb hits on the Plague Tanks at New Agamand. Do not return to him at Westguard Keep until you have accomplished that.", completion = "Nicely done, {name}, nicely done!\n\n\n\nThat'll show those good-for-nothing Forsaken to think about messing with us!\n\nI'd say you've earned yourself something from the treasury!", sourceObjectiveStatus = "unverified-source-field" }
quests[11333] = { id = 11333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the World of Spirits", description = "While the Explorers' League may discern bits and pieces of the past through their archaeological findings and the Vice Admiral might extract some knowledge of the present through brute force, the truth lies with the spirits.\n\nWith the proper reagents I am able to see into the spirit world. It is there that the past, present and future of Northrend resides.\n\nIf you wish to learn more, I will require my reagent pouch. It was lost in a ship that is now at the bottom of Daggercap Bay, just east of here.", sourceObjective = "Thoralius the Wise at Valgarde wants you to find his Reagent Pouch.", progress = "Have you found my reagent pouch?", completion = "A bit worse for the wear but still functional.\n\n<Thoralius reaches into the pouch and removes some odd looking roots.>\n\nNow to place them in the fire and inhale!\n\n<Thoralius throws the roots into the smoldering incense burner.>\n\n<Thoralius inhales deeply. His body begins to quiver.>\n\nWha... What... It cannot be... I cannot...", sourceObjectiveStatus = "unverified-source-field" }
quests[11334] = { id = 11334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Shoots, He Scores!" }
quests[11335] = { id = 11335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", sourceObjective = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "Excellent news, {class}!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", sourceObjectiveStatus = "unverified-source-field" }
quests[11336] = { id = 11336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", sourceObjective = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "Just what I wanted to hear!  A victory in Alterac Valley - even a temporary one - is crucial to our overall strategy against the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11337] = { id = 11337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "The fight against the Horde knows no boundaries, {name}.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war.\n\nGo into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.", sourceObjective = "Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "We've come one step closer to achieving total victory over the Horde.  We cannot allow the enemy to obtain a foothold in this world or any other.", sourceObjectiveStatus = "unverified-source-field" }
quests[11338] = { id = 11338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", sourceObjective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "What news do you bring from the front, {name}?", completion = "Excellent work, {name}.  The integrity of our borders must be preserved at all costs!", sourceObjectiveStatus = "unverified-source-field" }
quests[11339] = { id = 11339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", sourceObjective = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "You're back already.  Do you bring news of victory?", completion = "You've brought great honor to the Horde, {name}.  Your victory today will ensure a thousand victories tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[11340] = { id = 11340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", sourceObjective = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "There is no greater honor than driving invaders from Horde territories.  We salute your great courage in aiding our forces today!", sourceObjectiveStatus = "unverified-source-field" }
quests[11341] = { id = 11341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference.\n\nWe cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!", sourceObjective = "Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran,  or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "You bring honor to us all, {name}.  We must show the enemy that we will fight them wherever we find them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11342] = { id = 11342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", sourceObjective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "The Horde is in your debt, {name}.  You've made your people proud with your courage in defending our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[11343] = { id = 11343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Echo of Ymiron", description = "The spirit world has fallen under the sway of the Lich King. Fearsome creatures made of pure nightmare now stand watch over the realm of the elements. I sense that these val'kyr are guarding a terrible secret.\n\nI am too old and weak to survive another journey. You must go in my place, {name}.\n\nTake this incense burner to Wyrmskull Village and use it to enter the spirit world. Find the large dwelling in the northeast! Avoid the val'kyr at all costs lest they make you a permanent fixture in their world.", sourceObjective = "Thoralius the Wise wants you to search Wyrmskull Village while you are in the spirit world and find information about the Secrets of Wyrmskull.", progress = "What have you discovered?", completion = "I do not understand. The creatures that you saw looked like the vrykul that are attacking Valgarde?", sourceObjectiveStatus = "unverified-source-field" }
quests[11344] = { id = 11344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anguish of Nifflevar", description = "All that we know of the vrykul indicates that they only recently appeared in Northrend. Why, then, are we seeing vrykul in visions that date back 15,000 years? Surely if the vrykul had previously existed in Northrend we would have known.\n\nYou must press on to Nifflevar. To get there you must go northeast, through Wyrmskull Village, and take the path leading up through the dam. Nifflevar is on the bluffs of the fjord.\n\nUse the incense burner once you arrive at Nifflevar and search the area for clues.", sourceObjective = "Thoralius the Wise wants you to search Nifflevar while you are in the spirit world and find information about the Secrets of Nifflevar.", progress = "What have you discovered?", completion = "Human children born of vrykul? And Ymiron ordered the deaths of all human born offspring?\n\n<Thoralius goes silent for a moment.>\n\nAs much as I wish to deny what is so plainly presented to me, I cannot. There is no extinct \"missing link\" to humans as the Explorers' League proposed. The vrykul are the missing link. They are the progenitors of humanity.", sourceObjectiveStatus = "unverified-source-field" }
quests[11345] = { id = 11345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prizes for Pellets" }
quests[11346] = { id = 11346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Book of Runes", description = "The vast rocky area to the southeast, Giants' Run, has been overrun by Iron Dwarves. Scouts have reported seeing the dwarves coaxing stone giants from the ground, then carving runes on them.\n\nI can't fathom their motives, but I suspect they're somehow trying to turn the giants into weapons. The iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me, {name}.", sourceObjective = "Prospector Belvar at Fort Wildervar wants you to bring him The Book of Runes.", progress = "Have you recovered the book?", completion = "<Prospector Belvar browses the book of runes.>\n\nHmm... there's so much here. I'm going to need some time to study it, and if we hope to understand these runes, we'll need to try to make our own.", sourceObjectiveStatus = "unverified-source-field" }
quests[11348] = { id = 11348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rune of Command", description = "Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.", sourceObjective = "Prospector Belvar at Fort Wildervar wants you to test the Rune of Command and defeat Binder Murdis.", progress = "Have you tried the rune?", completion = "You've done well in defeating Binder Murdis, but the Iron Dwarves won't give up easily.\n\nWe've made a lot of progress in understanding how they manipulate runes. Perhaps next time we encounter them, our knowledge will give us an advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[11349] = { id = 11349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Runes", description = "I've got a set of picks, hammers, and chisels with me, but they won't work for carving these runes. The tools used by the Iron Dwarves are imbued with magic during their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.\n\nI believe I know how it works, but without a set of those tools, I can't be certain. Look for kits resembling mine near the Iron Dwarf pavilions at Giants' Run and bring them to me.", sourceObjective = "Bring a set of Iron Rune Carving Tools to Prospector Belvar at Fort Wildervar.", progress = "Have you returned with those tools?", completion = "<Belvar handles the tools carefully.>\n\nI'm going to try these out. If we're to understand the Iron Dwarves' motives and defeat them, I need to know exactly what the runes are doing.", sourceObjectiveStatus = "unverified-source-field" }
quests[11350] = { id = 11350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Book of Runes", description = "Chieftain Ashtotem dispatched me on a scouting mission to Giants' Run, a broad, rocky plateau to the southeast, past the Frozen Glade.\n\nThe area has been taken over by Iron Dwarves who seem to be altering the giants as they emerge from the earth.\n\nThe iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me. It's the only way we'll understand their plans.", sourceObjective = "Longrunner Pembe at Camp Winterhoof wants you to bring him The Book of Runes.", progress = "Have you recovered the book?", completion = "<The longrunner browses the book of runes.>\n\nI'm no loremaster, but I have some familiarity with the language of the Iron Dwarves. I think the runes they're carving on the giants are derived from their spoken language, but there are some differences.", sourceObjectiveStatus = "unverified-source-field" }
quests[11351] = { id = 11351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Runes", description = "I think I've figured out what the Iron Dwarves are doing. The tools they use are imbued with magic during their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.\n\nIf I had a set of those tools, I could mimic the runes in the book. I captured one of these boxes from one of the pavilions at Giants' Run, but it was empty. Look for similar boxes and recover a set of tools from them.", sourceObjective = "Bring a set of Iron Rune Carving Tools to Longrunner Pembe at Camp Winterhoof.", progress = "Have you returned with those tools?", completion = "<Pembe examines the tools.>\n\nThese are more delicate than I'd thought. Allow me a moment to try them out.", sourceObjectiveStatus = "unverified-source-field" }
quests[11352] = { id = 11352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rune of Command", description = "Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.", sourceObjective = "Longrunner Pembe at Camp Winterhoof wants you to test the Rune of Command and defeat Binder Murdis.", completion = "You've done well in defeating Binder Murdis, but the Iron Dwarves won't give up easily.\n\nAs my people move north, I'm certain we will encounter the Iron Dwarves again. Next time, we will be prepared to thwart them before they can dig in.", sourceObjectiveStatus = "unverified-source-field" }
quests[11354] = { id = 11354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Nazan's Riding Crop", description = "Today I have a buyer who is interested in a piece that's held by the mount of Illidan's herald. I, of course, speak of Vazruden the Herald and his dragon mount, Nazan.\n\nIf you want the finder's fee that I offer in return, find them flying above the Ramparts at Hellfire Citadel and return with the dragon's riding crop.\n\nMy sources tell me that the item in question is personally held by the dragon. It is said that Nazan refuses to allow Vazruden to strike him with it.", sourceObjective = "Wind Trader Zhareem has asked you to obtain Nazan's Riding Crop. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The riding crop please.", completion = "Another soon-to-be satisfied customer. It looks like it's in fine condition. You are to be rewarded.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
